/* DAWAH X — ahmad, অধ্যায় 17 · খণ্ড 17 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][17]=[[3201,3201,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ وَعْلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَهْدَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاوِيَةَ ‏ ‏خَمْرٍ وَقَالَ إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ فَدَعَا رَجُلًا فَسَارَّهُ فَقَالَ مَا أَمَرْتَهُ قَالَ أَمَرْتُهُ بِبَيْعِهَا قَالَ ‏ ‏فَإِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا قَالَ فَصُبَّتْ ‏","","",""],[3202,3202,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وَحَدَّثَنِي ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَسَفَتْ الشَّمْسُ فَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ مَعَهُ فَقَامَ قِيَامًا طَوِيلًا قَالَ نَحْوًا مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏قَالَ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْأَوَّلِ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ قَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ قَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ انْصَرَفَ وَقَدْ تَجَلَّتْ الشَّمْسُ فَقَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمْ ذَلِكَ فَاذْكُرُوا اللَّهَ قَالُوا يَا رَسُولَ اللَّهِ رَأَيْنَاكَ تَنَاوَلْتَ شَيْئًا فِي مَقَامِكَ هَذَا ثُمَّ رَأَيْنَاكَ تَكَعْكَعْتَ قَالَ إِنِّي رَأَيْتُ الْجَنَّةَ ‏ ‏أَوْ أُرِيتُ الْجَنَّةَ ‏ ‏وَلَمْ يَشُكَّ ‏ ‏إِسْحَاقُ ‏ ‏قَالَ رَأَيْتُ الْجَنَّةَ ‏ ‏فَتَنَاوَلْتُ مِنْهَا عُنْقُودًا وَلَوْ أَخَذْتُهُ لَأَكَلْتُمْ مِنْهُ مَا بَقِيَتْ الدُّنْيَا وَرَأَيْتُ النَّارَ فَلَمْ أَرَ كَالْيَوْمِ مَنْظَرًا أَفْظَعَ وَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ قَالُوا لِمَ يَا رَسُولَ اللَّهِ قَالَ بِكُفْرِهِنَّ قَالَ أَيَكْفُرْنَ بِاللَّهِ عَزَّ وَجَلَّ قَالَ لَا وَلَكِنْ يَكْفُرْنَ الْعَشِيرَ وَيَكْفُرْنَ الْإِحْسَانَ لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ كُلَّهُ ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ ‏","","",""],[3203,3203,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْفَضْلُ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَتْ امْرَأَةٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏تَسْتَفْتِيهِ فَجَعَلَ ‏ ‏الْفَضْلُ ‏ ‏يَنْظُرُ إِلَيْهَا وَتَنْظُرُ إِلَيْهِ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْرِفُ وَجْهَ ‏ ‏الْفَضْلِ ‏ ‏إِلَى الشِّقِّ الْآخَرِ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ فَرِيضَةَ اللَّهِ عَلَى عِبَادِهِ فِي الْحَجِّ أَدْرَكَتْ ‏ ‏أَبِي شَيْخًا كَبِيرًا لَا يَسْتَطِيعُ أَنْ يَثْبُتَ عَلَى الرَّاحِلَةِ أَفَأَحُجُّ عَنْهُ قَالَ نَعَمْ وَذَلِكَ فِي حَجَّةِ الْوَدَاعِ ‏","","",""],[3204,3204,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي ‏ ‏أَسَمِعْتُهُ ‏ ‏مِنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَمْ نُبِّئْتُهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِعَرَفَةَ ‏ ‏وَهُوَ يَأْكُلُ رُمَّانًا وَقَالَ ‏ ‏أَفْطَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏وَبَعَثَتْ إِلَيْهِ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[3205,3205,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَحَدُ ابْنَيْ ‏ ‏الْعَبَّاسِ ‏ ‏إِمَّا ‏ ‏الْفَضْلُ ‏ ‏وَإِمَّا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ فَقَالَ إِنَّ أَبِي ‏ ‏أَوْ أُمِّي ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَأَكْبَرُ ظَنِّي أَنَّهُ قَالَ أَبِي ‏ ‏كَبِيرٌ وَلَمْ يَحُجَّ فَإِنْ أَنَا حَمَلْتُهُ عَلَى بَعِيرٍ لَمْ يَثْبُتْ عَلَيْهِ وَإِنْ شَدَدْتَهُ عَلَيْهِ لَمْ آمَنْ عَلَيْهِ أَفَأَحُجُّ عَنْهُ قَالَ أَكُنْتَ قَاضِيًا دَيْنًا لَوْ كَانَ عَلَيْهِ قَالَ نَعَمْ قَالَ ‏ ‏فَاحْجُجْ عَنْهُ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[3206,3206,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏ضَمَّنِي إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏اللَّهُمَّ عَلِّمْهُ الْكِتَابَ ‏","","",""],[3207,3207,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمَّارٌ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ خَمْسٍ وَسِتِّينَ ‏","","",""],[3208,3208,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ فَعَرَضُوا عَلَيْهِ الْوَضُوءَ فَقَالَ ‏ ‏إِنَّمَا أُمِرْتُ بِالْوُضُوءِ إِذَا قُمْتُ إِلَى الصَّلَاةِ ‏","","",""],[3209,3209,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ فَقَالُوا أَلَا ‏ ‏نَأْتِيكَ بِوَضُوءٍ فَقَالَ ‏ ‏أُصَلِّي فَأَتَوَضَّأُ ‏","","",""],[3210,3210,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَوَّرَ صُورَةً كُلِّفَ يَوْمَ الْقِيَامَةِ أَنْ يَنْفُخَ فِيهَا وَعُذِّبَ وَلَنْ يَنْفُخَ فِيهَا وَمَنْ تَحَلَّمَ كُلِّفَ يَوْمَ الْقِيَامَةِ أَنْ يَعْقِدَ شَعِيرَتَيْنِ ‏ ‏أَوْ قَالَ بَيْنَ شَعِيرَتَيْنِ ‏ ‏وَعُذِّبَ وَلَنْ يَعْقِدَ بَيْنَهُمَا وَمَنْ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ يَكْرَهُونَهُ صُبَّ فِي أُذُنَيْهِ ‏ ‏الْآنُكُ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏يَعْنِي الرَّصَاصَ ‏","","",""],[3211,3211,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَكَحَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ مُحْرِمٌ وَبَنَى بِهَا حَلَالًا ‏ ‏بِسَرِفَ ‏ ‏وَمَاتَتْ ‏ ‏بِسَرِفَ ‏","","",""],[3212,3212,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فِي ‏ ‏الْجَدِّ ‏ ‏أَمَّا الَّذِي قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا مِنْ هَذِهِ الْأُمَّةِ خَلِيلًا لَاتَّخَذْتُهُ فَإِنَّهُ قَضَاهُ أَبًا ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏","","",""],[3213,3213,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ الْعُطَارِدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنًَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ ‏","","",""],[3214,3214,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ فِي السُّجُودِ فِي ‏ ‏ص ‏ ‏لَيْسَتْ مِنْ عَزَائِمِ السُّجُودِ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏","","",""],[3215,3215,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي غَنِيَّةَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏مُجَاهِدًا ‏ ‏عَنْ السَّجْدَةِ الَّتِي فِي ‏ ‏ص ‏ ‏فَقَالَ نَعَمْ سَأَلْتُ عَنْهَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ أَتَقْرَأُ هَذِهِ الْآيَةَ ‏ { ‏وَمِنْ ذُرِّيَّتِهِ ‏ ‏دَاوُدَ ‏ ‏وَسُلَيْمَانَ ‏ ‏وَفِي آخِرِهَا ‏ ‏فَبِهُدَاهُمْ ‏ ‏اقْتَدِهْ ‏} ‏قَالَ ‏ ‏أُمِرَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقْتَدِيَ ‏ ‏بِدَاوُدَ ‏","","",""],[3216,3216,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَقُمْتُ أُصَلِّي مَعَهُ فَقُمْتُ عَنْ شِمَالِهِ فَقَالَ لِي هَكَذَا فَأَخَذَ بِرَأْسِي فَأَقَامَنِي عَنْ يَمِينِهِ ‏","","",""],[3217,3217,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ ‏ ‏أُنْبِئْتُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَجَاءَ الْمَلَكُ بِهَا حَتَّى انْتَهَى إِلَى مَوْضِعِ ‏ ‏زَمْزَمَ ‏ ‏فَضَرَبَ بِعَقِبِهِ فَفَارَتْ عَيْنًا فَعَجِلَتْ الْإِنْسَانَةُ فَجَعَلَتْ تَقْدَحُ فِي شَنَّتِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِمَ اللَّهُ ‏ ‏أُمَّ إِسْمَاعِيلَ ‏ ‏لَوْلَا أَنَّهَا عَجِلَتْ لَكَانَتْ ‏ ‏زَمْزَمُ ‏ ‏عَيْنًا مَعِينًا ‏","","",""],[3218,3218,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَنِي سَدُوسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ الْقُبْلَةِ لِلصَّائِمِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصِيبُ مِنْ الرُّءُوسِ وَهُوَ صَائِمٌ ‏ ‏حَدَّثَنَاه ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[3219,3219,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ الْأَعْرَجِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏فَقَالَ ‏ ‏إِذَا رَأَيْتَ هِلَالَ الْمُحَرَّمِ فَاعْدُدْ فَإِذَا أَصْبَحْتَ مِنْ تَاسِعَةٍ فَأَصْبِحْ صَائِمًا ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏فَأُنْبِئْتُ عَنْ ‏ ‏الْحَكَمِ ‏ ‏أَنَّهُ قَالَ ‏ ‏فَقُلْتُ أَكَذَاكَ صَامَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[3220,3220,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي الْحَسَنِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي الْحَسَنِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَسَأَلَهُ رَجُلٌ فَقَالَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏إِنِّي رَجُلٌ إِنَّمَا مَعِيشَتِي مِنْ صَنْعَةِ يَدِي وَإِنِّي أَصْنَعُ هَذِهِ التَّصَاوِيرَ قَالَ فَإِنِّي لَا أُحَدِّثُكَ إِلَّا بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَوَّرَ صُورَةً فَإِنَّ اللَّهَ عَزَّ وَجَلَّ مُعَذِّبُهُ يَوْمَ الْقِيَامَةِ حَتَّى يَنْفُخَ فِيهَا الرُّوحَ وَلَيْسَ بِنَافِخٍ فِيهَا أَبَدًا قَالَ فَرَبَا لَهَا الرَّجُلُ رَبْوَةً شَدِيدَةً فَاصْفَرَّ وَجْهُهُ فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَيْحَكَ إِنْ أَبَيْتَ إِلَّا أَنْ تَصْنَعَ فَعَلَيْكَ بِهَذَا الشَّجَرِ وَكُلِّ شَيْءٍ لَيْسَ فِيهِ رُوحٌ ‏","","",""],[3221,3221,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَحِلَّ فَحَلَلْنَا فَلُبِسَتْ الثِّيَابُ وَسَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏وَنُكِحَتْ النِّسَاءُ ‏","","",""],[3222,3222,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ قَالَ ‏ ‏طَاوُسٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُصَلِّ فِيهِ وَلَكِنَّهُ اسْتَقْبَلَ زَوَايَاهُ ‏","","",""],[3223,3223,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ فِي السَّفَرِ وَالْحَضَرِ ‏","","",""],[3224,3224,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَفْطَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏وَبَعَثَتْ إِلَيْهِ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[3225,3225,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا أُمِرَ أَنْ يَقْرَأَ فِيهِ وَسَكَتَ فِيمَا أُمِرَ أَنْ يَسْكُتَ فِيهِ ‏ { ‏وَمَا كَانَ رَبُّكَ نَسِيًّا ‏} ‏وَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}","","",""],[3226,3226,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[3227,3227,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوا لَيْلَةَ الْقَدْرِ فِي الْعَشْرِ الْأَوَاخِرِ فِي تَاسِعَةٍ تَبْقَى أَوْ خَامِسَةٍ تَبْقَى أَوْ سَابِعَةٍ تَبْقَى ‏","","",""],[3228,3228,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏الْجَعْدُ ‏ ‏صَاحِبُ ‏ ‏الْحِلَى ‏ ‏أَبُو عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَجَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَرْوِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذَلِكَ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ وَإِنْ هُوَ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ سَيِّئَةً وَاحِدَةً ‏","","",""],[3229,3229,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَهَسَ مِنْ كَتِفٍ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[3230,3230,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏صَاحِبٍ ‏ ‏لَهُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْجُمُعَةِ ‏ ‏بِالْجُمُعَةِ ‏ ‏وَالْمُنَافِقِينَ ‏","","",""],[3231,3231,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَنْبَأَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ زَوْجَ ‏ ‏بَرِيرَةَ ‏ ‏كَانَ عَبْدًا أَسْوَدَ يُسَمَّى ‏ ‏مُغِيثًا ‏ ‏وَكُنْتُ أَرَاهُ يَتْبَعُهَا فِي سِكَكِ ‏ ‏الْمَدِينَةِ ‏ ‏يَعْصِرُ عَيْنَيْهِ عَلَيْهَا قَالَ ‏ ‏فَقَضَى فِيهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ قَضِيَّاتٍ قَضَى أَنَّ الْوَلَاءَ لِمَنْ أَعْتَقَ وَخَيَّرَهَا وَأَمَرَهَا أَنْ تَعْتَدَّ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏مَرَّةً عِدَّةَ الْحُرَّةِ ‏ ‏قَالَ وَتُصُدِّقَ عَلَيْهَا بِصَدَقَةٍ فَأَهْدَتْ مِنْهَا إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هُوَ عَلَيْهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ ‏","","",""],[3232,3232,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَعَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ ‏ ‏الْأَشَجُّ ‏ ‏أَخُو ‏ ‏بَنِي عَصَرٍ ‏ ‏فَقَالُوا يَا نَبِيَّ اللَّهِ إِنَّا حَيٌّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَإِنَّ بَيْنَنَا وَبَيْنَكَ كُفَّارَ ‏ ‏مُضَرَ ‏ ‏وَإِنَّا لَا نَصِلُ إِلَيْكَ إِلَّا فِي الشَّهْرِ الْحَرَامِ فَمُرْنَا بِأَمْرٍ إِذَا عَمِلْنَا بِهِ دَخَلْنَا الْجَنَّةَ ‏ ‏وَنَدْعُو بِهِ مَنْ وَرَاءَنَا فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ أَمَرَهُمْ ‏ ‏أَنْ يَعْبُدُوا اللَّهَ وَلَا يُشْرِكُوا بِهِ شَيْئًا وَأَنْ يَصُومُوا رَمَضَانَ وَأَنْ يَحُجُّوا ‏ ‏الْبَيْتَ ‏ ‏وَأَنْ يُعْطُوا ‏ ‏الْخُمُسَ ‏ ‏مِنْ الْمَغَانِمِ وَنَهَاهُمْ عَنْ أَرْبَعٍ عَنْ الشُّرْبِ فِي ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏فَقَالُوا فَفِيمَ نَشْرَبُ يَا رَسُولَ اللَّهِ قَالَ عَلَيْكُمْ ‏ ‏بِأَسْقِيَةِ ‏ ‏الْأَدَمِ ‏ ‏الَّتِي ‏ ‏يُلَاثُ ‏ ‏عَلَى أَفْوَاهِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ ‏ ‏الْأَشَجُّ ‏ ‏أَخُو ‏ ‏بَنِي عَصَرٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[3233,3233,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَنْبَأَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْوَتْرِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ قَالَ وَسَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[3234,3234,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدِرْعُهُ مَرْهُونَةٌ عِنْدَ يَهُودِيٍّ بِثَلَاثِينَ صَاعًا مِنْ شَعِيرٍ أَخَذَهُ طَعَامًا لِأَهْلِهِ ‏","","",""],[3235,3235,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفُ بْنُ أَبِي جَمِيلَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْفَارِسِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي النَّوْمِ زَمَنَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ وَكَانَ ‏ ‏يَزِيدُ ‏ ‏يَكْتُبُ الْمَصَاحِفَ قَالَ فَقُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي النَّوْمِ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ كَانَ يَقُولُ ‏ ‏إِنَّ الشَّيْطَانَ لَا يَسْتَطِيعُ أَنْ يَتَشَبَّهَ بِي فَمَنْ رَآنِي فِي النَّوْمِ فَقَدْ رَآنِي فَهَلْ تَسْتَطِيعُ أَنْ ‏ ‏تَنْعَتَ ‏ ‏لَنَا هَذَا الرَّجُلَ الَّذِي رَأَيْتَ قَالَ قُلْتُ نَعَمْ رَأَيْتُ رَجُلًا بَيْنَ الرَّجُلَيْنِ جِسْمُهُ وَلَحْمُهُ أَسْمَرُ إِلَى الْبَيَاضِ حَسَنُ ‏ ‏الْمَضْحَكِ أَكْحَلُ الْعَيْنَيْنِ جَمِيلُ دَوَائِرِ الْوَجْهِ قَدْ مَلَأَتْ لِحْيَتُهُ مِنْ هَذِهِ إِلَى هَذِهِ حَتَّى كَادَتْ تَمْلَأُ نَحْرَهُ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏لَا أَدْرِي مَا كَانَ مَعَ هَذَا مِنْ ‏ ‏النَّعْتِ ‏ ‏قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَوْ رَأَيْتَهُ ‏ ‏فِي الْيَقَظَةِ مَا اسْتَطَعْتَ أَنْ ‏ ‏تَنْعَتَهُ ‏ ‏فَوْقَ هَذَا ‏","","",""],[3236,3236,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏سِرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏لَا نَخَافُ إِلَّا اللَّهَ عَزَّ وَجَلَّ نُصَلِّي رَكْعَتَيْنِ ‏","","",""],[3237,3237,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[3238,3238,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[3239,3239,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏التَّمِيمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَجَدَ يُرَى بَيَاضُ إِبْطَيْهِ وَهُوَ سَاجِدٌ ‏","","",""],[3240,3240,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَعْتَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الطَّائِفِ ‏ ‏مَنْ خَرَجَ مِنْ رَقِيقِ الْمُشْرِكِينَ ‏","","",""],[3241,3241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏سَلْمٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏مُسَاعَاةَ ‏ ‏فِي الْإِسْلَامِ مَنْ ‏ ‏سَاعَى ‏ ‏فِي الْجَاهِلِيَّةِ فَقَدْ أَلْحَقْتُهُ بِعَصَبَتِهِ وَمَنْ ادَّعَى وَلَدَهُ مِنْ غَيْرِ رِشْدَةٍ فَلَا يَرِثُ وَلَا يُورَثُ ‏","","",""],[3242,3242,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ وَهُوَ مُحْرِمٌ فَرَدَّهُ وَقَالَ ‏ ‏لَوْلَا أَنَّا مُحْرِمُونَ لَقَبِلْنَاهُ مِنْكَ ‏","","",""],[3243,3243,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏حَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي الثَّوْبِ الْمَصْبُوغِ مَا لَمْ يَكُنْ بِهِ نَفْضٌ وَلَا رَدْعٌ ‏","","",""],[3244,3244,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَرِضَ ‏ ‏أَبُو طَالِبٍ ‏ ‏دَخَلَ عَلَيْهِ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مِنْهُمْ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَالُوا يَا ‏ ‏أَبَا طَالِبٍ ‏ ‏ابْنُ أَخِيكَ يَشْتِمُ آلِهَتَنَا يَقُولُ وَيَقُولُ وَيَفْعَلُ وَيَفْعَلُ فَأَرْسِلْ إِلَيْهِ فَانْهَهُ قَالَ فَأَرْسَلَ إِلَيْهِ ‏ ‏أَبُو طَالِبٍ ‏ ‏وَكَانَ قُرْبَ ‏ ‏أَبِي طَالِبٍ ‏ ‏مَوْضِعُ رَجُلٍ فَخَشِيَ إِنْ دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى عَمِّهِ أَنْ يَكُونَ أَرَقَّ لَهُ عَلَيْهِ ‏ ‏فَوَثَبَ ‏ ‏فَجَلَسَ فِي ذَلِكَ الْمَجْلِسِ فَلَمَّا دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَجِدْ مَجْلِسًا إِلَّا عِنْدَ الْبَابِ فَجَلَسَ فَقَالَ ‏ ‏أَبُو طَالِبٍ ‏ ‏يَا ابْنَ أَخِي إِنَّ قَوْمَكَ يَشْكُونَكَ يَزْعُمُونَ أَنَّكَ تَشْتُمُ آلِهَتَهُمْ وَتَقُولُ وَتَقُولُ وَتَفْعَلُ وَتَفْعَلُ فَقَالَ يَا عَمِّ ‏ ‏إِنِّي إِنَّمَا أُرِيدُهُمْ عَلَى كَلِمَةٍ وَاحِدَةٍ تَدِينُ لَهُمْ بِهَا ‏ ‏الْعَرَبُ ‏ ‏وَتُؤَدِّي إِلَيْهِمْ بِهَا ‏ ‏الْعَجَمُ ‏ ‏الْجِزْيَةَ ‏ ‏قَالُوا وَمَا هِيَ نَعَمْ وَأَبِيكَ عَشْرًا قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَقَامُوا وَهُمْ يَنْفُضُونَ ثِيَابَهُمْ وَهُمْ يَقُولُونَ ‏ { ‏أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ ‏} ‏قَالَ ثُمَّ قَرَأَ حَتَّى بَلَغَ ‏ { ‏لَمَّا يَذُوقُوا عَذَابِ ‏}","","",""],[3245,3245,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَتْهُ امْرَأَةٌ فَقَالَتْ إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرِ رَمَضَانَ ‏ ‏فَأَقْضِيهِ عَنْهَا قَالَ أَرَأَيْتَكِ لَوْ كَانَ عَلَيْهَا دَيْنٌ كُنْتِ تَقْضِينَهُ قَالَتْ نَعَمْ قَالَ ‏ ‏فَدَيْنُ اللَّهِ عَزَّ وَجَلَّ أَحَقُّ أَنْ ‏ ‏يُقْضَى ‏","","",""],[3246,3246,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَيِّمُ ‏ ‏أَوْلَى بِنَفْسِهَا مِنْ ‏ ‏وَلِيِّهَا ‏ ‏وَالْبِكْرُ ‏ ‏تُسْتَأْمَرُ ‏ ‏فِي نَفْسِهَا وَصَمْتُهَا إِقْرَارُهَا ‏","","",""],[3247,3247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَيُّ الْقِرَاءَتَيْنِ تَعُدُّونَ أَوَّلَ قَالُوا قِرَاءَةَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ لَا بَلْ هِيَ الْآخِرَةُ كَانَ ‏ ‏يُعْرَضُ الْقُرْآنُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُلِّ عَامٍ مَرَّةً فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ عُرِضَ عَلَيْهِ مَرَّتَيْنِ ‏ ‏فَشَهِدَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَعَلِمَ مَا نُسِخَ مِنْهُ وَمَا بُدِّلَ ‏","","",""],[3248,3248,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الصَّوَّافُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْمُكَاتِبِ ‏ ‏يُقْتَلُ ‏ ‏يُودَى ‏ ‏لِمَا أَدَّى مِنْ ‏ ‏مُكَاتَبَتِهِ ‏ ‏دِيَةَ ‏ ‏الْحُرِّ وَمَا بَقِيَ ‏ ‏دِيَةَ ‏ ‏الْعَبْدِ ‏","","",""],[3249,3249,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الصَّوَّافُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏زَيْدِ بْنِ عَلِيٍّ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَمَرَّ شَيْخٌ يُقَالُ لَهُ ‏ ‏شُرَحْبِيلُ أَبُو سَعْدٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا سَعْدٍ ‏ ‏مِنْ أَيْنَ جِئْتَ فَقَالَ مِنْ عِنْدِ أَمِيرِ الْمُؤْمِنِينَ حَدَّثْتُهُ بِحَدِيثٍ فَقَالَ لَأَنْ يَكُونَ هَذَا الْحَدِيثُ حَقًّا أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي حُمْرُ النَّعَمِ قَالَ حَدِّثْ بِهِ الْقَوْمَ قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ تُدْرِكُ لَهُ ابْنَتَانِ فَيُحْسِنُ إِلَيْهِمَا مَا صَحِبَتَاهُ ‏ ‏أَوْ صَحِبَهُمَا ‏ ‏إِلَّا أَدْخَلَتَاهُ الْجَنَّةَ ‏","","",""],[3250,3250,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْوَدَ النَّاسِ بِالْخَيْرِ وَكَانَ أَجْوَدَ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏وَكَانَ يَلْقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏كُلَّ لَيْلَةٍ فِي رَمَضَانَ حَتَّى ‏ ‏يَنْسَلِخَ ‏ ‏يَعْرِضُ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُرْآنَ فَإِذَا لَقِيَهُ ‏ ‏جِبْرِيلُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْوَدَ بِالْخَيْرِ مِنْ الرِّيحِ الْمُرْسَلَةِ ‏","","",""],[3251,3251,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا مِنْ ثِيَابِكُمْ الْبَيَاضَ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ وَإِنَّ خَيْرَ ‏ ‏أَكْحَالِكُمُ ‏ ‏الْإِثْمِدُ ‏ ‏إِنَّهُ يُنْبِتُ الشَّعْرَ ‏ ‏وَيَجْلُو ‏ ‏الْبَصَرَ ‏","","",""],[3252,3252,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏كَتَبْتُ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَكَتَبَ إِلَيَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْيَمِينَ عَلَى الْمُدَّعَى عَلَيْهِ وَلَوْ أُعْطِيَ النَّاسُ بِدَعْوَاهُمْ لَادَّعَى أُنَاسٌ أَمْوَالَ النَّاسِ وَدِمَاءَهُمْ ‏","","",""],[3253,3253,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ يَتَصَدَّقُ بِدِينَارٍ فَإِنْ لَمْ يَجِدْ فَنِصْفِ دِينَارٍ ‏","","",""],[3254,3254,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو جَمْرَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ سَنَةً ‏ ‏وَبِالْمَدِينَةِ ‏ ‏عَشْرًا يُوحَى إِلَيْهِ وَمَاتَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ سَنَةً ‏","","",""],[3255,3255,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَخْطُبُ إِلَى جِذْعٍ فَلَمَّا صُنِعَ الْمِنْبَرُ فَتَحَوَّلَ إِلَيْهِ حَنَّ الْجِذْعُ فَأَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْتَضَنَهُ فَسَكَنَ وَقَالَ ‏ ‏لَوْ لَمْ أَحْتَضِنْهُ لَحَنَّ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَاه ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَخْطُبُ إِلَى جِذْعِ النَّخْلَةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[3256,3256,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَعَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَظْمًا ثُمَّ صَلَّى وَلَمْ يَمَسَّ مَاءً ‏","","",""],[3257,3257,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَضُرُّوكَ شَيْئًا وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ ‏} ‏قَالَ كَانَ ‏ ‏بَنُو النَّضِيرِ ‏ ‏إِذَا قَتَلُوا قَتِيلًا مِنْ ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏أَدَّوْا إِلَيْهِمْ نِصْفَ الدِّيَةِ وَإِذَا قَتَلَ ‏ ‏بَنُو قُرَيْظَةَ ‏ ‏مِنْ ‏ ‏بَنِي النَّضِيرِ ‏ ‏قَتِيلًا أَدَّوْا إِلَيْهِمْ الدِّيَةَ كَامِلَةً فَسَوَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنهُمْ الدِّيَةَ ‏","","",""],[3258,3258,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏وَمُجَاهِدٍ ‏ ‏وَعَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النُّفَسَاءَ وَالْحَائِضَ تَغْتَسِلُ وَتُحْرِمُ ‏ ‏وَتَقْضِي الْمَنَاسِكَ كُلَّهَا غَيْرَ أَنْ لَا تَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏حَتَّى تَطْهُرَ ‏","","",""],[3259,3259,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِي ‏ ‏ص ‏","","",""],[3260,3260,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏رِشْدِينُ بْنُ كُرَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُمْتُ إِلَى جَنْبِهِ عَنْ يَسَارِهِ فَأَخَذَنِي فَأَقَامَنِي عَنْ يَمِينِهِ قَالَ وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَنَا يَوْمَئِذٍ ابْنُ عَشْرِ سِنِينَ ‏","","",""],[3261,3261,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏دُعِينَا إِلَى طَعَامٍ ‏ ‏وَفِينَا ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏ومِقْسَمٌ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَلَمَّا وُضِعَ الطَّعَامُ قَالَ ‏ ‏سَعِيدٌ ‏ ‏كُلُّكُمْ بَلَغَهُ مَا قِيلَ فِي الطَّعَامِ ‏ ‏قَالَ ‏ ‏مِقْسَمٌ ‏ ‏حَدِّثْ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏مَنْ لَمْ يَكُنْ يَسْمَعُ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَ الطَّعَامُ فَلَا تَأْكُلُوا مِنْ وَسَطِهِ فَإِنَّ الْبَرَكَةَ تَنْزِلُ وَسَطَهُ وَكُلُوا مِنْ حَافَتَيْهِ ‏ ‏أَوْ حَافَتَيْهَا ‏","","",""],[3262,3262,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏طَاوُسًا ‏ ‏يُخْبِرُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ شَهِدَ قَضَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ فَجَاءَ ‏ ‏حَمَلُ بْنُ مَالِكِ بْنِ النَّابِغَةِ ‏ ‏فَقَالَ كُنْتُ بَيْنَ امْرَأَتَيْنِ فَضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى بِمِسْطَحٍ فَقَتَلَتْهَا وَجَنِينَهَا ‏ ‏فَقَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنِينِهَا بِغُرَّةٍ عَبْدٍ وَأَنْ تُقْتَلَ ‏ ‏فَقُلْتُ ‏ ‏لِعَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏كَذَا وَكَذَا فَقَالَ لَقَدْ شَكَّكْتَنِي ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏كَانَ بَيْنِي وَبَيْنَ امْرَأَتَيَّ فَضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى ‏","","",""],[3263,3263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءٌ الْخُرَاسَانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏خِذَامًا أَبَا وَدِيعَةَ ‏ ‏أَنْكَحَ ‏ ‏ابْنَتَهُ ‏ ‏رَجُلًا فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاشْتَكَتْ إِلَيْهِ أَنَّهَا أُنْكِحَتْ وَهِيَ كَارِهَةٌ فَانْتَزَعَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ زَوْجِهَا وَقَالَ ‏ ‏لَا تُكْرِهُوهُنَّ قَالَ فَنَكَحَتْ بَعْدَ ذَلِكَ ‏ ‏أَبَا لُبَابَةَ الْأَنْصَارِيَّ ‏ ‏وَكَانَتْ ‏ ‏ثَيِّبًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءٌ الْخُرَاسَانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَحْوَهُ وَزَادَ ثُمَّ جَاءَتْهُ بَعْدُ فَأَخْبَرَتْهُ أَنْ قَدْ ‏ ‏مَسَّهَا ‏ ‏فَمَنَعَهَا أَنْ تَرْجِعَ إِلَى زَوْجِهَا الْأَوَّلِ وَقَالَ اللَّهُمَّ إِنْ كَانَ إِيمَانُهُ أَنْ يُحِلَّهَا ‏ ‏لِرَفَاعَةَ ‏ ‏فَلَا يَتِمَّ لَهُ نِكَاحُهَا مَرَّةً أُخْرَى ثُمَّ أَتَتْ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فِي خِلَافَتِهِمَا فَمَنَعَاهَا كِلَاهُمَا ‏","","",""],[3264,3264,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏طَاوُسًا ‏ ‏أخْبَرَهُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ وَهُوَ يَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏بِإِنْسَانٍ يَقُودُ إِنْسَانًا ‏ ‏بِخِزَامَةٍ ‏ ‏فِي أَنْفِهِ فَقَطَعَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ فَأَمَرَهُ أَنْ يَقُودَهُ بِيَدِهِ ‏","","",""],[3265,3265,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏طَاوُسًا ‏ ‏أَخْبَرَهُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ وَهُوَ يَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏بِإِنْسَانٍ قَدْ رَبَطَ يَدَهُ إِلَى إِنْسَانٍ آخَرَ ‏ ‏بِسَيْرٍ ‏ ‏أَوْ بِخَيْطٍ أَوْ بِشَيْءٍ ‏ ‏غَيْرِ ذَلِكَ فَقَطَعَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ ثُمَّ قَالَ قُدْهُ بِيَدِهِ ‏","","",""],[3266,3266,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسِ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَفَرٍ يَرْمُونَ فَقَالَ ‏ ‏رَمْيًا بَنِي ‏ ‏إِسْمَاعِيلَ ‏ ‏فَإِنَّ أَبَاكُمْ كَانَ رَامِيًا ‏","","",""],[3267,3267,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ وَلَقَدْ سَمِعْتُ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَجِيءُ الْمَقْتُولُ يَوْمَ الْقِيَامَةِ آخِذًا رَأْسَهُ إِمَّا قَالَ بِشِمَالِهِ ‏ ‏وَإِمَّا بِيَمِينِهِ ‏ ‏تَشْخَبُ أَوْدَاجُهُ فِي قُبُلِ عَرْشِ الرَّحْمَنِ تَبَارَكَ وَتَعَالَى يَقُولُ يَا رَبِّ سَلْ هَذَا فِيمَ قَتَلَنِي ‏","","",""],[3268,3268,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏بَلَغَنِي أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَجَدَ ‏ ‏رُئِيَ ‏ ‏بَيَاضُ إِبْطَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏التَّمِيمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَ ذَلِكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3269,3269,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِّمُوا وَيَسِّرُوا وَلَا تُعَسِّرُوا وَإِذَا غَضِبْتَ فَاسْكُتْ وَإِذَا غَضِبْتَ فَاسْكُتْ وَإِذَا غَضِبْتَ فَاسْكُتْ ‏","","",""],[3270,3270,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا لِي عَهْدٌ بِأَهْلِي مُنْذُ عَفَارِ النَّخْلِ ‏ ‏أَوْ إِغْفَارِهِ ‏ ‏قَالَ وَعَفَارُ النَّخْلِ ‏ ‏أَوْ إِغْفَارُهَا ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تُؤَبَّرُ ‏ ‏ثُمَّ تُعْفَرُ ‏ ‏أَوْ تُغْفَرُ ‏ ‏أَرْبَعِينَ يَوْمًا لَا تُسْقَى بَعْدَ الْإِبَارِ قَالَ فَوَجَدْتُ رَجُلًا مَعَ امْرَأَتِي وَكَانَ زَوْجُهَا مُصْفَرًّا حَمْشًا ‏ ‏سَبْطَ ‏ ‏الشَّعْرِ وَالَّذِي رُمِيَتْ بِهِ رَجُلٌ خَدْلٌ إِلَى السَّوَادِ جَعْدٌ ‏ ‏قَطَطٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَيِّنْ اللَّهُمَّ بَيِّنْ ثُمَّ لَاعَنَ بَيْنَهُمَا فَجَاءَتْ بِوَلَدٍ يُشْبِهُ الَّذِي رُمِيَتْ بِهِ ‏","","",""],[3271,3271,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِوُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا بِمَاءٍ فَجَعَل يَغْرِفُ بِيَدِهِ الْيُمْنَى ثُمَّ يَصُبُّ عَلَى الْيُسْرَى ‏","","",""],[3272,3272,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سُمَيْعٍ الزَّيَّاتِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ كُنْتُ قُمْتُ إِلَى جَنْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى شِمَالِهِ ‏ ‏فَأَدَارَنِي فَجَعَلَنِي عَنْ يَمِينِهِ ‏","","",""],[3273,3273,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَاةٍ ‏ ‏لِمَيْمُونَةَ ‏ ‏مَيْتَةٍ فَقَالَ ‏ ‏أَلَا اسْتَمْتَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏قَالُوا وَكَيْفَ وَهِيَ مَيْتَةٌ فَقَالَ إِنَّمَا حُرِّمَ لَحْمُهَا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَكَانَ ‏ ‏الزُّهْرِيُّ ‏ ‏يُنْكِرُ الدِّبَاغَ وَيَقُولُ يُسْتَمْتَعُ بِهَا عَلَى كُلِّ حَالٍ ‏","","",""],[3274,3274,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏تَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏احْتَزَّ ‏ ‏مِنْ كَتِفٍ فَأَكَلَ ثُمَّ مَضَى إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏","","",""],[3275,3275,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جِئْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَوْ قَالَ يَوْمَ الْفَتْحِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي أَنَا ‏ ‏وَالْفَضْلُ ‏ ‏مُرْتَدِفَانِ ‏ ‏عَلَى ‏ ‏أَتَانٍ ‏ ‏فَقَطَعْنَا الصَّفَّ وَنَزَلْنَا عَنْهَا ثُمَّ دَخَلْنَا الصَّفَّ ‏ ‏وَالْأَتَانُ ‏ ‏تَمُرُّ بَيْنَ أَيْدِيهِمْ لَمْ تَقْطَعْ صَلَاتَهُمْ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏كُنْتُ رَدِيفَ ‏ ‏الْفَضْلِ ‏ ‏عَلَى ‏ ‏أَتَانٍ ‏ ‏فَجِئْنَا وَنَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ ‏ ‏بِمِنًي ‏","","",""],[3276,3276,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَأَى الصُّوَرَ فِي ‏ ‏الْبَيْتِ ‏ ‏يَعْنِي ‏ ‏الْكَعْبَةَ ‏ ‏لَمْ يَدْخُلْ وَأَمَرَ بِهَا فَمُحِيَتْ وَرَأَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَإِسْمَاعِيلَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏بِأَيْدِيهِمَا ‏ ‏الْأَزْلَامُ ‏ ‏فَقَالَ قَاتَلَهُمْ اللَّهُ وَاللَّهِ مَا ‏ ‏اسْتَقْسَمَا ‏ ‏بِالْأَزْلَامِ ‏ ‏قَطُّ ‏","","",""],[3277,3277,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي تَاسِعَةٍ تَبْقَى أَوْ خَامِسَةٍ تَبْقَى أَوْ سَابِعَةٍ تَبْقَى ‏","","",""],[3278,3278,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏حَجَمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدٌ ‏ ‏لِبَنِي بَيَاضَةَ ‏ ‏وَأَعْطَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْرَهُ وَلَوْ كَانَ حَرَامًا لَمْ يُعْطِهِ قَالَ وَأَمَرَ مَوَالِيَهُ أَنْ يُخَفِّفُوا عَنْهُ بَعْضَ خَرَاجِهِ ‏","","",""],[3279,3279,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏وَأَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَنَّثَ ‏ ‏مِنْ الرِّجَالِ ‏ ‏وَالْمُتَرَجِّلَاتِ ‏ ‏مِنْ النِّسَاءِ ‏","","",""],[3280,3280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَقُمْتُ مَعَهُ عَلَى يَسَارِهِ فَأَخَذَ بِيَدِي فَجَعَلَنِي عَنْ يَمِينِهِ ‏ ‏ثُمَّ صَلَّى ثَلَاثَ عَشْرَةَ رَكْعَةً ‏ ‏حَزَرْتُ ‏ ‏قَدْرَ قِيَامِهِ فِي كُلِّ رَكْعَةٍ قَدْرَ ‏ ‏يَا أَيُّهَا الْمُزَّمِّلُ ‏","","",""],[3281,3281,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ إِلَى ‏ ‏مَكَّةَ ‏ ‏فِي شَهْرِ رَمَضَانَ فَصَامَ حَتَّى مَرَّ بِغَدِيرٍ فِي الطَّرِيقِ وَذَلِكَ فِي ‏ ‏نَحْرِ الظَّهِيرَةِ ‏ ‏قَالَ فَعَطِشَ النَّاسُ وَجَعَلُوا يَمُدُّونَ أَعْنَاقَهُمْ وَتَتُوقُ أَنْفُسُهُمْ إِلَيْهِ قَالَ ‏ ‏فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَدَحٍ فِيهِ مَاءٌ فَأَمْسَكَهُ عَلَى يَدِهِ حَتَّى رَآهُ النَّاسُ ثُمَّ شَرِبَ فَشَرِبَ النَّاسُ ‏","","",""],[3282,3282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏ثُمَّ سَمِعْتُهُ بَعْدُ ‏ ‏يَعْنِي ‏ ‏عَطَاءً ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كَانَتْ شَاةٌ ‏ ‏أَوْ ‏ ‏دَاجِنَةٌ ‏ ‏لِإِحْدَى نِسَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَاتَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلَّا اسْتَمْتَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏أَوْ ‏ ‏مَسْكِهَا ‏","","",""],[3283,3283,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏خُصَيْفٌ ‏ ‏أَنَّ ‏ ‏مِقْسَمًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏قَالَ أَنَا عِنْدَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ سَأَلَهُ ‏ ‏سَعْدٌ ‏ ‏وَابْنُ عُمَرَ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَضَى ‏ ‏عُمَرُ ‏ ‏لِسَعْدٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقُلْتُ يَا ‏ ‏سَعْدُ ‏ ‏قَدْ عَلِمْنَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى خُفَّيْهِ وَلَكِنْ أَقَبْلَ ‏ ‏الْمَائِدَةِ ‏ ‏أَمْ بَعْدَهَا قَالَ ‏ ‏فَقَالَ ‏ ‏رَوْحٌ ‏ ‏أَوْ بَعْدَهَا قَالَ ‏ ‏لَا يُخْبِرُكَ أَحَدٌ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَيْهِمَا بَعْدَمَا أُنْزِلَتْ ‏ ‏الْمَائِدَةُ ‏ ‏فَسَكَتَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[3284,3284,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ عَرْقًا أَتَاهُ الْمُؤَذِّنُ فَوَضَعَهُ وَقَامَ إِلَى الصَّلَاةِ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[3285,3285,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏أَنَّ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏أخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَرَأَى ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ فَقَالَ أَتَدْرِي مِمَّا أَتَوَضَّأُ قَالَ لَا قَالَ أَتَوَضَّأُ مِنْ ‏ ‏أَثْوَارِ ‏ ‏أَقِطٍ أَكَلْتُهَا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا أُبَالِي مِمَّا تَوَضَّأْتَ أَشْهَدُ لَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفَ لَحْمٍ ثُمَّ قَامَ إِلَى الصَّلَاةِ وَمَا تَوَضَّأَ ‏ ‏قَالَ ‏ ‏وَسُلَيْمَانُ ‏ ‏حَاضِرٌ ذَلِكَ مِنْهُمَا جَمِيعًا ‏","","",""],[3286,3286,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ ‏ ‏عِلْمِي وَالَّذِي يَخْطِرُ عَلَى بَالِي ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أَخْبَرَنِي أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ بِفَضْلِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَذَلِكَ أَنِّي سَأَلْتُهُ عَنْ إِخْلَاءِ الْجُنُبَيْنِ جَمِيعًا ‏","","",""],[3287,3287,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏أَيُّ حِينٍ أَحَبُّ إِلَيْكَ أَنْ أُصَلِّيَ الْعِشَاءَ إِمَامًا أَوْ ‏ ‏خِلْوًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَعْتَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً بِالْعِشَاءِ حَتَّى رَقَدَ النَّاسُ وَاسْتَيْقَظُوا وَرَقَدُوا وَاسْتَيْقَظُوا فَقَامَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ الصَّلَاةَ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَخَرَجَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ الْآنَ يَقْطُرُ رَأْسُهُ مَاءً وَاضِعٌ يَدَهُ عَلَى شَقِّ رَأْسِهِ فَقَالَ لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُصَلُّوهَا كَذَلِكَ ‏","","",""],[3288,3288,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏صَلَّيْتُ وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِيًا جَمِيعًا وَسَبْعًا جَمِيعًا ‏","","",""],[3289,3289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏طَاوُسًا ‏ ‏أخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏تَهَجَّدَ ‏ ‏مِنْ اللَّيْلِ ‏ ‏فَذَكَرَ نَحْوَ دُعَاءِ ‏ ‏سُفْيَانَ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏وَعْدُكَ الْحَقُّ وَقَوْلُكَ الْحَقُّ وَلِقَاؤُكَ الْحَقُّ وَقَالَ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ أَنْتَ إِلَهِي لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[3290,3290,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْوَدَ الْبَشَرِ فَمَا هُوَ إِلَّا أَنْ يَدْخُلَ شَهْرُ رَمَضَانَ فَيُدَارِسَهُ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَهُوَ أَجْوَدُ مِنْ الرِّيحِ ‏","","",""],[3291,3291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَشَفَ عَنْ وَجْهِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مَيِّتٌ ‏ ‏بُرْدَ ‏ ‏حِبَرَةٍ ‏ ‏كَانَ مُسَجًّى عَلَيْهِ فَنَظَرَ إِلَى وَجْهِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَكَبَّ عَلَيْهِ فَقَبَّلَهُ ‏","","",""],[3292,3292,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ذَكَرَ قَوْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْغُسْلِ يَوْمَ الْجُمُعَةِ ‏ ‏قَالَ ‏ ‏طَاوُسٌ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏وَيَمَسُّ طِيبًا أَوْ دُهْنًا إِنْ كَانَ عِنْدَ أَهْلِهِ قَالَ لَا أَعْلَمُهُ ‏","","",""],[3293,3293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي خِدَاشٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَشْرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمَقْبُرَةِ وَهِيَ عَلَى طَرِيقِهِ الْأُولَى أَشَارَ بِيَدِهِ وَرَاءَ الضَّفِيرِ ‏ ‏أَوْ قَالَ وَرَاءَ الضَّفِيرَةِ شَكَّ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فَقَالَ ‏ ‏نِعْمَ الْمَقْبُرَةُ هَذِهِ ‏ ‏فَقُلْتُ لِلَّذِي أَخْبَرَنِي أَخَصَّ الشِّعْبَ قَالَ هَكَذَا قَالَ فَلَمْ يُخْبِرْنِي أَنَّهُ خَصَّ شَيْئًا إِلَّا كَذَلِكَ أَشَارَ بِيَدِهِ وَرَاءَ الضَّفِيرَةِ ‏ ‏أَوْ الضَّفِيرِ ‏ ‏وَكُنَّا نَسْمَعُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَصَّ الشِّعْبَ الْمُقَابِلَ ‏ ‏لِلْبَيْتِ ‏","","",""],[3294,3294,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْكَرِيمِ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ فِي الْحَائِضِ نِصَابَ دِينَارٍ فَإِنْ أَصَابَهَا وَقَدْ أَدْبَرَ الدَّمُ عَنْهَا وَلَمْ تَغْتَسِلْ فَنِصْفُ دِينَارٍ كُلُّ ذَلِكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3295,3295,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُحَمَّدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُنْكِرُ أَنْ يُتَقَدَّمَ فِي صِيَامِ رَمَضَانَ إِذَا لَمْ يُرَ هِلَالُ شَهْرِ رَمَضَانَ وَيَقُولُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَمْ تَرَوْا الْهِلَالَ فَاسْتَكْمِلُوا ثَلَاثِينَ لَيْلَةً ‏","","",""],[3296,3296,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَا عَلِمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَرَّى صِيَامَ يَوْمٍ يَبْتَغِي فَضْلَهُ عَلَى غَيْرِهِ إِلَّا هَذَا الْيَوْمَ ‏ ‏لِيَوْمِ عَاشُورَاءَ ‏ ‏أَوْ رَمَضَانَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أَوْ شَهْرُ رَمَضَانَ ‏","","",""],[3297,3297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عَطَاءٌ ‏ ‏دَعَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏إِلَى طَعَامٍ فَقَالَ إِنِّي صَائِمٌ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا تَصُمْ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرِّبَ إِلَيْهِ حِلَابٌ فِيهِ لَبَنٌ يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَشَرِبَ مِنْهُ فَلَا تَصُمْ فَإِنَّ النَّاسَ مُسْتَنُّونَ بِكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏وَرَوْحٌ ‏ ‏إِنَّ النَّاسَ يَسْتَنُّونَ بِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زَكَرِيَّاءُ بْنُ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَطَاءً ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏دَعَا ‏ ‏الْفَضْلَ ‏","","",""],[3298,3298,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا مَعْبَدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنْ الْمَكْتُوبَةِ كَانَ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كُنْتُ أَعْلَمُ إِذَا انْصَرَفُوا بِذَلِكَ إِذَا سَمِعْتُهُ ‏","","",""],[3299,3299,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ لَيْلَةً عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مُتَطَوِّعًا مِنْ اللَّيْلِ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْقِرْبَةِ فَتَوَضَّأَ فَقَامَ ‏ ‏يُصَلِّي فَقُمْتُ لَمَّا رَأَيْتُهُ صَنَعَ ذَلِكَ فَتَوَضَّأْتُ مِنْ الْقِرْبَةِ ثُمَّ قُمْتُ إِلَى شِقِّهِ الْأَيْسَرِ فَأَخَذَ بِيَدِي مِنْ وَرَاءِ ظَهْرِي يَعْدِلُنِي كَذَلِكَ مِنْ وَرَاءِ ظَهْرِي إِلَى الشِّقِّ الْأَيْمَنِ ‏","","",""],[3300,3300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏وَعَنْ ‏ ‏كُرَيْبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السَّفَرِ قَالَ قُلْنَا بَلَى قَالَ كَانَ ‏ ‏إِذَا زَاغَتْ الشَّمْسُ فِي مَنْزِلِهِ جَمَعَ ‏ ‏بَيْنَ الظُّهْرِ وَالْعَصْرِ قَبْلَ أَنْ يَرْكَبَ وَإِذَا لَمْ تَزِغْ لَهُ فِي مَنْزِلِهِ سَارَ حَتَّى إِذَا حَانَتْ الْعَصْرُ نَزَلَ فَجَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَإِذَا حَانَتْ الْمَغْرِبُ فِي مَنْزِلِهِ جَمَعَ بَيْنَهَا وَبَيْنَ الْعِشَاءِ وَإِذَا لَمْ تَحِنْ فِي مَنْزِلِهِ رَكِبَ حَتَّى إِذَا حَانَتْ الْعِشَاءُ نَزَلَ فَجَمَعَ بَيْنَهُمَا ‏","","",""],[3301,3301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَحْسِبُ كُلَّ شَيْءٍ بِمَنْزِلَةِ الطَّعَامِ ‏","","",""],[3302,3302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَلَقَّى الرُّكْبَانُ وَأَنْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا قَوْلُهُ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏قَالَ لَا يَكُونُ لَهُ سِمْسَارًا ‏","","",""],[3303,3303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏لَئِنْ رَأَيْتُ ‏ ‏مُحَمَّدًا ‏ ‏يُصَلِّي عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏لَأَطَأَنَّ ‏ ‏عَلَى عُنُقِهِ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَوْ فَعَلَ لَأَخَذَتْهُ الْمَلَائِكَةُ عِيَانًا ‏","","",""],[3304,3304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَانِي رَبِّي عَزَّ وَجَلَّ اللَّيْلَةَ فِي أَحْسَنِ صُورَةٍ ‏ ‏أَحْسِبُهُ ‏ ‏يَعْنِي فِي النَّوْمِ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَلْ تَدْرِي فِيمَ يَخْتَصِمُ الْمَلَأُ الْأَعْلَى قَالَ قُلْتُ لَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَ يَدَهُ بَيْنَ كَتِفَيَّ حَتَّى وَجَدْتُ بَرْدَهَا بَيْنَ ثَدْيَيَّ ‏ ‏أَوْ قَالَ نَحْرِي ‏ ‏فَعَلِمْتُ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَلْ تَدْرِي فِيمَ يَخْتَصِمُ الْمَلَأُ الْأَعْلَى قَالَ قُلْتُ نَعَمْ يَخْتَصِمُونَ فِي الْكَفَّارَاتِ وَالدَّرَجَاتِ قَالَ وَمَا الْكَفَّارَاتُ وَالدَّرَجَاتُ قَالَ الْمُكْثُ فِي الْمَسَاجِدِ وَالْمَشْيُ عَلَى الْأَقْدَامِ إِلَى الْجَمَاعَاتِ وَإِبْلَاغُ الْوُضُوءِ فِي ‏ ‏الْمَكَارِهِ ‏ ‏وَمَنْ فَعَلَ ذَلِكَ عَاشَ بِخَيْرٍ وَمَاتَ بِخَيْرٍ وَكَانَ مِنْ خَطِيئَتِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ وَقُلْ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِذَا صَلَّيْتَ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْخَيْرَاتِ وَتَرْكَ الْمُنْكَرَاتِ وَحُبَّ الْمَسَاكِينِ وَإِذَا أَرَدْتَ بِعِبَادِكَ فِتْنَةً أَنْ تَقْبِضَنِي إِلَيْكَ غَيْرَ مَفْتُونٍ قَالَ وَالدَّرَجَاتُ بَذْلُ الطَّعَامِ وَإِفْشَاءُ السَّلَامِ وَالصَّلَاةُ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ ‏","","",""],[3305,3305,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ الْمَلَأَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏اجْتَمَعُوا فِي ‏ ‏الْحِجْرِ ‏ ‏فَتَعَاهَدُوا بِاللَّاتِ وَالْعُزَّى وَمَنَاةَ الثَّالِثَةِ الْأُخْرَى لَوْ قَدْ رَأَيْنَا ‏ ‏مُحَمَّدًا ‏ ‏قُمْنَا إِلَيْهِ قِيَامَ رَجُلٍ وَاحِدٍ فَلَمْ نُفَارِقْهُ حَتَّى نَقْتُلَهُ قَالَ فَأَقْبَلَتْ ‏ ‏فَاطِمَةُ ‏ ‏تَبْكِي حَتَّى دَخَلَتْ عَلَى أَبِيهَا فَقَالَتْ هَؤُلَاءِ الْمَلَأُ مِنْ قَوْمِكَ فِي ‏ ‏الْحِجْرِ ‏ ‏قَدْ ‏ ‏تَعَاهَدُوا ‏ ‏أَنْ لَوْ قَدْ رَأَوْكَ قَامُوا إِلَيْكَ فَقَتَلُوكَ فَلَيْسَ مِنْهُمْ رَجُلٌ إِلَّا قَدْ عَرَفَ نَصِيبَهُ مِنْ دَمِكَ قَالَ يَا بُنَيَّةُ ‏ ‏أَدْنِي وَضُوءًا فَتَوَضَّأَ ثُمَّ دَخَلَ عَلَيْهِمْ الْمَسْجِدَ فَلَمَّا رَأَوْهُ قَالُوا هُوَ هَذَا فَخَفَضُوا أَبْصَارَهُمْ وَعُقِرُوا فِي مَجَالِسِهِمْ فَلَمْ يَرْفَعُوا إِلَيْهِ أَبْصَارَهُمْ وَلَمْ يَقُمْ مِنْهُمْ رَجُلٌ فَأَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قَامَ عَلَى رُءُوسِهِمْ فَأَخَذَ قَبْضَةً مِنْ تُرَابٍ فَحَصَبَهُمْ بِهَا وَقَالَ شَاهَتْ الْوُجُوهُ قَالَ فَمَا أَصَابَتْ رَجُلًا مِنْهُمْ حَصَاةٌ إِلَّا قَدْ قُتِلَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏كَافِرًا ‏","","",""],[3306,3306,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏رَايَةَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏وَرَايَةَ ‏ ‏الْأَنْصَارِ ‏ ‏مَعَ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏وَكَانَ ‏ ‏إِذَا اسْتَحَرَّ الْقَتْلُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا يَكُونَ تَحْتَ رَايَةِ ‏ ‏الْأَنْصَارِ ‏","","",""],[3307,3307,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَسُئِلَ هَلْ شَهِدْتَ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ وَلَوْلَا قَرَابَتِي مِنْهُ مَا شَهِدْتُهُ مِنْ الصِّغَرِ ‏ ‏فَصَلَّى رَكْعَتَيْنِ ثُمَّ خَطَبَ ثُمَّ أَتَى الْعَلَمَ الَّذِي عِنْدَ دَارِ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏فَوَعَظَ النِّسَاءَ وَذَكَّرَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ فَأَهْوَيْنَ إِلَى آذَانِهِنَّ وَحُلُوقِهِنَّ فَتَصَدَّقْنَ بِهِ قَالَ فَدَفَعْنَهُ إِلَى ‏ ‏بِلَالٍ ‏","","",""],[3308,3308,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ لَا يَرَى أَنْ يَنْزِلَ ‏ ‏الْأَبْطَحَ ‏ ‏وَيَقُولُ إِنَّمَا ‏ ‏أَقَامَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏","","",""],[3309,3309,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُودَى ‏ ‏الْمُكَاتَبُ ‏ ‏بِحِصَّةِ مَا أَدَّى دِيَةَ الْحُرِّ وَمَا بَقِيَ دِيَةَ عَبْدٍ ‏","","",""],[3310,3310,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ خَالَتِي ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏فَبِتُّ عِنْدَهَا فَوَجَدْتُ لَيْلَتَهَا تِلْكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ثُمَّ دَخَلَ بَيْتَهُ فَوَضَعَ رَأْسَهُ عَلَى وِسَادَةٍ مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ فَجِئْتُ فَوَضَعْتُ رَأْسِي عَلَى نَاحِيَةٍ مِنْهَا فَاسْتَيْقَظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ فَإِذَا عَلَيْهِ لَيْلٌ فَسَبَّحَ وَكَبَّرَ حَتَّى نَامَ ثُمَّ اسْتَيْقَظَ وَقَدْ ذَهَبَ شَطْرُ اللَّيْلِ ‏ ‏أَوْ قَالَ ثُلُثَاهُ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ جَاءَ إِلَى قِرْبَةٍ عَلَى ‏ ‏شَجْبٍ ‏ ‏فِيهَا مَاءٌ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ثُمَّ غَسَلَ قَدَمَيْهِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏حَسِبْتُهُ قَالَ ثَلَاثًا ثَلَاثًا ‏ ‏ثُمَّ أَتَى مُصَلَّاهُ فَقُمْتُ وَصَنَعْتُ كَمَا صَنَعَ ثُمَّ جِئْتُ فَقُمْتُ عَنْ يَسَارِهِ وَأَنَا أُرِيدُ أَنْ أُصَلِّيَ بِصَلَاتِهِ فَأَمْهَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا عَرَفَ أَنِّي أُرِيدُ أَنْ أُصَلِّيَ بِصَلَاتِهِ لَفَتَ يَمِينَهُ فَأَخَذَ بِأُذُنِي فَأَدَارَنِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَى أَنَّ عَلَيْهِ لَيْلًا رَكْعَتَيْنِ فَلَمَّا ظَنَّ أَنَّ الْفَجْرَ قَدْ دَنَا قَامَ فَصَلَّى سِتَّ رَكَعَاتٍ أَوْتَرَ بِالسَّابِعَةِ حَتَّى إِذَا أَضَاءَ الْفَجْرُ قَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ وَضَعَ جَنْبَهُ فَنَامَ حَتَّى سَمِعْتُ ‏ ‏فَخِيخَهُ ‏ ‏ثُمَّ جَاءَهُ ‏ ‏بِلَالٌ ‏ ‏فَآذَنَهُ بِالصَّلَاةِ فَخَرَجَ فَصَلَّى وَمَا مَسَّ مَاءً ‏ ‏فَقُلْتُ ‏ ‏لِسَعِيدِ بْنِ جُبَيْرٍ ‏ ‏مَا أَحْسَنَ هَذَا فَقَالَ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏أَمَا وَاللَّهِ لَقَدْ قُلْتُ ذَاكَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏مَهْ إِنَّهَا لَيْسَتْ لَكَ وَلَا لِأَصْحَابِكَ إِنَّهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ كَانَ يَحْفَظُ ‏","","",""],[3311,3311,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ الرَّجُلِ إِذَا رَمَى الْجَمْرَةَ أَيَتَطَيَّبُ فَقَالَ أَمَّا أَنَا فَقَدْ ‏ ‏رَأَيْتُ الْمِسْكَ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَمِنْ الطِّيبِ هُوَ أَمْ لَا ‏","","",""],[3312,3312,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏حَدِّثْنِي عَنْ الرُّكُوبِ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَإِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّهَا سُنَّةٌ فَقَالَ صَدَقُوا وَكَذَبُوا قُلْتُ مَا صَدَقُوا وَكَذَبُوا مَاذَا قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏فَخَرَجُوا حَتَّى خَرَجَتْ ‏ ‏الْعَوَاتِقُ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُضْرَبُ عِنْدَهُ أَحَدٌ فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ وَهُوَ رَاكِبٌ وَلَوْ نَزَلَ لَكَانَ الْمَشْيُ أَحَبَّ إِلَيْهِ ‏","","",""],[3313,3313,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏سِرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏لَا نَخَافُ إِلَّا اللَّهَ عَزَّ وَجَلَّ نُصَلِّي رَكْعَتَيْنِ ‏","","",""],[3314,3314,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ الصَّلَاةِ ‏ ‏بِالْبَطْحَاءِ ‏ ‏إِذَا فَاتَنِي الصَّلَاةُ فِي الْجَمَاعَةِ فَقَالَ رَكْعَتَيْنِ تِلْكَ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3315,3315,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنِ ‏ ‏بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ وَهُوَ عَلَى بَعِيرِهِ وَخَلْفَهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَاسْتَسْقَى فَسَقَيْنَاهُ ‏ ‏نَبِيذًا ‏ ‏فَشَرِبَ ثُمَّ نَاوَلَ ‏ ‏فَضْلَهُ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَقَالَ قَدْ أَحْسَنْتُمْ وَأَجْمَلْتُمْ فَكَذَلِكَ فَافْعَلُوا فَنَحْنُ لَا نُرِيدُ أَنْ نُغَيِّرَ ذَلِكَ ‏","","",""],[3316,3316,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى ‏ ‏يَقْبِضَهُ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏وَأَظُنُّهُ قَالَ أَوْ عَلَفًا ‏","","",""],[3317,3317,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَقَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏زَمْزَمَ ‏ ‏فَشَرِبَ وَهُوَ قَائِمٌ ‏","","",""],[3318,3318,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَالْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[3319,3319,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ مِنْ الطَّعَامِ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَهَا ‏ ‏أَوْ يُلْعِقَهَا ‏","","",""],[3320,3320,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عِكْرِمَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ { ‏وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلَّا فِتْنَةً لِلنَّاسِ ‏} ‏قَالَ شَيْءٌ أُرِيَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْيَقَظَةِ رَآهُ بِعَيْنِهِ حِينَ ‏ ‏أُسْرِيَ ‏ ‏بِهِ إِلَى ‏ ‏بَيْتِ الْمَقْدِسِ ‏","","",""],[3321,3321,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيًا مَالًا لَأَحَبَّ أَنَّ لَهُ إِلَيْهِ مِثْلَهُ وَلَا يَمْلَأُ نَفْسَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ وَاللَّهُ يَتُوبُ عَلَى مَنْ تَابَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَلَا أَدْرِي أَمِنَ الْقُرْآنِ هُوَ أَمْ لَا ‏","","",""],[3322,3322,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ خَالِدِ بْنِ الْمُغِيرَةِ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏فَوَجَدْتُ لَيْلَتَهَا تِلْكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏يَزِيدَ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏حَتَّى ‏ ‏إِذَا طَلَعَ الْفَجْرُ الْأَوَّلُ أَمْسَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُنَيَّةً ‏ ‏حَتَّى إِذَا أَضَاءَ لَهُ الصُّبْحُ قَامَ فَصَلَّى الْوَتْرَ تِسْعَ رَكَعَاتٍ يُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ حَتَّى إِذَا فَرَغَ مِنْ وَتْرِهِ أَمْسَكَ يَسِيرًا حَتَّى إِذَا أَصْبَحَ فِي نَفْسِهِ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَكَعَ رَكْعَتَيْ الْفَجْرِ لِصَلَاةِ الصُّبْحِ ثُمَّ وَضَعَ جَنْبَهُ فَنَامَ حَتَّى سَمِعْتُ ‏ ‏جَخِيفَهُ قَالَ ثُمَّ جَاءَ ‏ ‏بِلَالٌ ‏ ‏فَنَبَّهَهُ لِلصَّلَاةِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى الصُّبْحَ ‏","","",""],[3323,3323,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ يَقُولُ ‏ ‏مَكَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ سَنَةً وَتُوُفِّيَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ سَنَةً ‏","","",""],[3324,3324,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أُمَّهُ ‏ ‏تُوُفِّيَتْ أَفَيَنْفَعُهَا إِنْ تَصَدَّقْتُ عَنْهَا فَقَالَ ‏ ‏نَعَمْ قَالَ فَإِنَّ لِي ‏ ‏مَخْرَفًا ‏ ‏وَأُشْهِدُكَ أَنِّي قَدْ تَصَدَّقْتُ بِهِ عَنْهَا ‏","","",""],[3325,3325,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ يَذْكُرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لِلْحَائِضِ أَنْ ‏ ‏تَصْدُرَ ‏ ‏قَبْلَ أَنْ تَطُوفَ إِذَا كَانَتْ قَدْ طَافَتْ فِي الْإِفَاضَةِ ‏","","",""],[3326,3326,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اسْتَفْتَى ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَذْرٍ ‏ ‏عَلَى ‏ ‏أُمِّهِ ‏ ‏تُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْضِهِ عَنْهَا ‏","","",""],[3327,3327,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏رَقَبَةَ بْنِ مَصْقَلَةَ بْنِ رَقَبَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ الْإِيَامِيِّ ‏ ‏عَنْ ‏ ‏سَعِيْدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏تَزَوَّجْ فَإِنَّ خَيْرَنَا كَانَ أَكْثَرَنَا نِسَاءً ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3328,3328,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَقُولُ أَنْبَأَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏تُوُفِّيَتْ أُمُّهُ وَهُوَ غَائِبٌ عَنْهَا فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏تُوُفِّيَتْ وَأَنَا غَائِبٌ عَنْهَا فَهَلْ يَنْفَعُهَا إِنْ تَصَدَّقْتُ عَنْهَا قَالَ نَعَمْ قَالَ فَإِنِّي أُشْهِدُكَ أَنَّ حَائِطِي ‏ ‏الْمَخْرَفَ ‏ ‏صَدَقَةٌ عَنْهَا ‏","","",""],[3329,3329,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ الْبَرَّاءِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ أَهَلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ فَقَدِمَ لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ فَصَلَّى بِنَا الصُّبْحَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏ثُمَّ قَالَ ‏ ‏مَنْ شَاءَ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَجْعَلْهَا ‏","","",""],[3330,3330,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِى سِنَانٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏الْأَقْرَعَ بْنَ حَابِسٍ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ كُلَّ عَامٍ فَقَالَ ‏ ‏لَا بَلْ حَجَّةٌ فَمَنْ حَجَّ بَعْدَ ذَلِكَ فَهُوَ تَطَوُّعٌ وَلَوْ قُلْتُ نَعَمْ لَوَجَبَتْ وَلَوْ وَجَبَتْ لَمْ تَسْمَعُوا وَلَمْ تُطِيعُوا ‏","","",""],[3331,3331,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَبْعَثَنَّ اللَّهُ تَبَارَكَ وَتَعَالَى الْحَجَرَ يَوْمَ الْقِيَامَةِ وَلَهُ عَيْنَانِ يُبْصِرُ بِهِمَا وَلِسَانٌ يَنْطِقُ يَشْهَدُ عَلَى مَنْ ‏ ‏اسْتَلَمَهُ ‏ ‏بِحَقٍّ ‏","","",""],[3332,3332,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ ‏ ‏اعْتَمَرُوا مِنْ ‏ ‏جِعِرَّانَةَ ‏ ‏فَاضْطَبَعُوا وَجَعَلُوا أَرْدِيَتَهُمْ تَحْتَ آبَاطِهِمْ وَوَضَعُوهَا عَلَى عَوَاتِقِهِمْ ثُمَّ ‏ ‏رَمَلُوا ‏","","",""],[3333,3333,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏يَا بَنِي أَخِي يَا ‏ ‏بَنِي هَاشِمٍ ‏ ‏تَعَجَّلُوا قَبْلَ زِحَامِ النَّاسِ وَلَا يَرْمِيَنَّ أَحَدٌ مِنْكُمْ ‏ ‏الْعَقَبَةَ ‏ ‏حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[3334,3334,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏كَامِلٌ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏قَالَ فَانْتَبَهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ثُمَّ رَكَعَ قَالَ فَرَأَيْتُهُ قَالَ فِي رُكُوعِهِ ‏ ‏سُبْحَانَ ‏ ‏رَبِّيَ الْعَظِيمِ ثُمَّ رَفَعَ رَأْسَهُ فَحَمِدَ اللَّهَ مَا شَاءَ أَنْ يَحْمَدَهُ قَالَ ثُمَّ سَجَدَ قَالَ فَكَانَ يَقُولُ فِي سُجُودِهِ سُبْحَانَ ‏ ‏رَبِّيَ الْأَعْلَى قَالَ ثُمَّ رَفَعَ رَأْسَهُ قَالَ فَكَانَ يَقُولُ فِيمَا بَيْنَ السَّجْدَتَيْنِ رَبِّ اغْفِرْ لِي وَارْحَمْنِي وَاجْبُرْنِي وَارْفَعْنِي وَارْزُقْنِي وَاهْدِنِي ‏","","",""],[3335,3335,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏قَالَ ‏ ‏تَرَاءَيْنَا هِلَالَ شَهْرِ رَمَضَانَ ‏ ‏بِذَاتِ عِرْقٍ ‏ ‏فَأَرْسَلْنَا إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَسْأَلُهُ فَقَالَ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ مَدَّهُ لِرُؤْيَتِهِ فَإِنْ ‏ ‏أُغْمِيَ ‏ ‏عَلَيْكُمْ فَأَكْمِلُوا الْعِدَّةَ ‏","","",""],[3336,3336,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍٍ ‏ ‏قَالَ ‏ ‏مَكَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ سَنَةً وَتُوُفِّيَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[3337,3337,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بُعِثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعِينَ سَنَةً ‏ ‏فَمَكَثَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ سَنَةً يُوحَى إِلَيْهِ ثُمَّ أُمِرَ بِالْهِجْرَةِ فَهَاجَرَ عَشْرَ سِنِينَ فَمَاتَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3338,3338,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو حَاضِرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏يُنْبَذُ فِيهِ فَقَالَ ‏ ‏نَهَى اللَّهُ وَرَسُولُهُ عَنْهُ فَانْطَلَقَ الرَّجُلُ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرَ لَهُ مَا قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏صَدَقَ قَالَ الرَّجُلُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَيُّ ‏ ‏جَرٍّ ‏ ‏نَهَى عَنْهُ قَالَ كُلُّ شَيْءٍ يُصْنَعُ مِنْ ‏ ‏مَدَرٍ ‏","","",""],[3339,3339,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏آيَةُ الدَّيْنِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ مَنْ جَحَدَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏قَالَهَا ثَلَاثَ مَرَّاتٍ إِنَّ اللَّهَ لَمَّا خَلَقَ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏مَسَحَ ظَهْرَهُ فَأَخْرَجَ مِنْهُ مَا هُوَ ‏ ‏ذَارِئٌ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ فَجَعَلَ يَعْرِضُهُمْ عَلَيْهِ فَرَأَى فِيهِمْ رَجُلًا يَزْهَرُ فَقَالَ أَيْ رَبِّ أَيُّ بَنِيَّ هَذَا قَالَ هَذَا ابْنُكَ ‏ ‏دَاوُدُ ‏ ‏قَالَ أَيْ رَبِّ كَمْ عُمْرُهُ قَالَ سِتُّونَ سَنَةً قَالَ أَيْ رَبِّ زِدْ فِي عُمْرِهِ قَالَ لَا إِلَّا أَنْ تَزِيدَهُ أَنْتَ مِنْ عُمْرِكَ فَكَانَ عُمْرُ ‏ ‏آدَمَ ‏ ‏أَلْفَ عَامٍ فَوَهَبَ لَهُ مِنْ عُمْرِهِ أَرْبَعِينَ عَامًا فَكَتَبَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ كِتَابًا وَأَشْهَدَ عَلَيْهِ الْمَلَائِكَةَ فَلَمَّا حُضِرَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَتْهُ الْمَلَائِكَةُ لِتَقْبِضَ رُوحَهُ فَقَالَ إِنَّهُ لَمْ يَحْضُرْ أَجَلِي قَدْ بَقِيَ مِنْ عُمْرِي أَرْبَعُونَ سَنَةً فَقَالُوا إِنَّكَ قَدْ وَهَبْتَهَا لِابْنِكَ ‏ ‏دَاوُدَ ‏ ‏قَالَ مَا فَعَلْتُ وَلَا وَهَبْتُ لَهُ شَيْئًا وَأَبْرَزَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ الْكِتَابَ فَأَقَامَ عَلَيْهِ الْمَلَائِكَةَ ‏","","",""],[3340,3340,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ الدُّؤَلِىِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ عَلَيْكُمْ الْحَجَّ فَقَالَ ‏ ‏الْأَقْرَعُ بْنُ حَابِسٍ ‏ ‏أَبَدًا يَا رَسُولَ اللَّهِ قَالَ بَلْ حَجَّةٌ وَاحِدَةٌ وَلَوْ قُلْتُ نَعَمْ لَوَجَبَتْ ‏","","",""],[3341,3341,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مَاتَتْ شَاةٌ ‏ ‏لِمَيْمُونَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلَّا اسْتَمْتَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏فَقَالُوا إِنَّهَا مَيْتَةٌ فَقَالَ إِنَّ ‏ ‏دِبَاغَ ‏ ‏الْأَدِيمِ ‏ ‏طُهُورُهُ ‏","","",""],[3342,3342,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏إِنِّي رَمَيْتُ بِسِتٍّ ‏ ‏أَوْ سَبْعٍ ‏ ‏قَالَ مَا أَدْرِي أَرَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَمْرَةَ بِسِتٍّ ‏ ‏أَوْ سَبْعٍ ‏","","",""],[3343,3343,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ فِي رَأْسِهِ مِنْ صُدَاعٍ وَجَدَهُ ‏","","",""],[3344,3344,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ عَلَى رَأْسِهِ ‏","","",""],[3345,3345,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏ثُمَّ ‏ ‏أَشْعَرَ ‏ ‏الْهَدْيَ ‏ ‏جَانِبَ السَّنَامِ الْأَيْمَنِ ثُمَّ ‏ ‏أَمَاطَ ‏ ‏عَنْهُ الدَّمَ ‏ ‏وَقَلَّدَهُ ‏ ‏نَعْلَيْنِ ثُمَّ رَكِبَ نَاقَتَهُ فَلَمَّا اسْتَوَتْ بِهِ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏أَحْرَمَ قَالَ فَأَحْرَمَ عِنْدَ الظُّهْرِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏بِالْحَجِّ ‏","","",""],[3346,3346,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَتَوَضَّأُ ثَلَاثًا يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَتَوَضَّأُ مَرَّةً مَرَّةً يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3347,3347,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏زَمْزَمَ ‏ ‏فَنَزَعْنَا لَهُ دَلْوًا فَشَرِبَ ثُمَّ ‏ ‏مَجَّ ‏ ‏فِيهَا ثُمَّ أَفْرَغْنَاهَا فِي ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ قَالَ لَوْلَا أَنْ تُغْلَبُوا عَلَيْهَا لَنَزَعْتُ بِيَدَيَّ ‏","","",""],[3348,3348,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ أَعْرَابِيًّا قَالَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا شَأْنُ آلِ ‏ ‏مُعَاوِيَةَ ‏ ‏يَسْقُونَ الْمَاءَ وَالْعَسَلَ وَآلُ فُلَانٍ يَسْقُونَ اللَّبَنَ وَأَنْتُمْ تَسْقُونَ ‏ ‏النَّبِيذَ ‏ ‏أَمِنْ بُخْلٍ بِكُمْ أَوْ حَاجَةٍ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا بِنَا بُخْلٌ وَلَا حَاجَةٌ وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنَا ‏ ‏وَرَدِيفُهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَاسْتَسْقَى فَسَقَيْنَاهُ مِنْ هَذَا ‏ ‏يَعْنِي ‏ ‏نَبِيذَ ‏ ‏السِّقَايَةِ فَشَرِبَ مِنْهُ وَقَالَ أَحْسَنْتُمْ هَكَذَا فَاصْنَعُوا ‏","","",""],[3349,3349,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏فَسَقَيْنَاهُ ‏ ‏فَشَرِبَ قَائِمًا ‏","","",""],[3350,3350,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي حَرِيزٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُنْكَحَ الْمَرْأَةُ عَلَى عَمَّتِهَا أَوْ عَلَى خَالَتِهَا ‏","","",""],[3351,3351,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ بِثَلَاثٍ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[3352,3352,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَا يَأْتِي عَلَى رُكْنٍ مِنْ أَرْكَانِ ‏ ‏الْبَيْتِ ‏ ‏إِلَّا ‏ ‏اسْتَلَمَهُ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُ ‏ ‏هَذَيْنِ الرُّكْنَيْنِ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَيْسَ مِنْ أَرْكَانِهِ شَيْءٌ مَهْجُورٌ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏الرُّكْنَيْنِ ‏ ‏الْيَمَانِيَ وَالْحَجَرَ ‏","","",""],[3353,3353,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَهُمَا يَطُوفَانِ حَوْلَ ‏ ‏الْبَيْتِ ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَسْتَلِمُ ‏ ‏الرُّكْنَيْنِ وَكَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَسْتَلِمُ ‏ ‏الْأَرْكَانَ كُلَّهَا فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَسْتَلِمُ إِلَّا هَذَيْنِ الرُّكْنَيْنِ ‏ ‏الْيَمَانِيَ وَالْأَسْوَدَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَيْسَ مِنْهَا شَيْءٌ مَهْجُورٌ ‏","","",""],[3354,3354,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏يَزْعُمُ قَوْمُكَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏رَمَلَ ‏ ‏بِالْبَيْتِ ‏ ‏وَأَنَّ ذَلِكَ سُنَّةٌ قَالَ صَدَقُوا وَكَذَبُوا قُلْتُ مَا صَدَقُوا وَكَذَبُوا قَالَ صَدَقُوا قَدْ ‏ ‏رَمَلَ ‏ ‏بِالْبَيْتِ ‏ ‏وَكَذَبُوا لَيْسَتْ بِسُنَّةٍ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏قَالَتْ دَعُوا ‏ ‏مُحَمَّدًا ‏ ‏وَأَصْحَابَهُ زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏حَتَّى يَمُوتُوا مَوْتَ ‏ ‏النَّغَفِ ‏ ‏فَلَمَّا صَالَحُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَنْ يَجِيئُوا مِنْ الْعَامِ الْمُقْبِلِ فَيُقِيمُوا ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثًا فَقَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْعَامِ الْمُقْبِلِ وَالْمُشْرِكُونَ مِنْ قِبَلِ ‏ ‏قُعَيْقِعَانَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْمُلُوا ‏ ‏بِالْبَيْتِ ‏ ‏ثَلَاثًا وَلَيْسَتْ بِسُنَّةٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي عَاصِمٍ الْغَنَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[3355,3355,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏قُرَيْشًا ‏ ‏قَالَتْ إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏وَأَصْحَابَهُ قَدْ ‏ ‏وَهَنَتْهُمْ ‏ ‏حُمَّى ‏ ‏يَثْرِبَ ‏ ‏فَلَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَامِهِ الَّذِي اعْتَمَرَ فِيهِ قَالَ لِأَصْحَابِهِ ‏ ‏ارْمُلُوا ‏ ‏بِالْبَيْتِ ‏ ‏لِيَرَى الْمُشْرِكُونَ قُوَّتَكُمْ فَلَمَّا ‏ ‏رَمَلُوا ‏ ‏قَالَتْ ‏ ‏قُرَيْشٌ ‏ ‏مَا ‏ ‏وَهَنَتْهُمْ ‏","","",""],[3356,3356,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَجَرُ الْأَسْوَدُ مِنْ الْجَنَّةِ وَكَانَ أَشَدَّ بَيَاضًا مِنْ الثَّلْجِ حَتَّى سَوَّدَتْهُ خَطَايَا أَهْلِ الشِّرْكِ ‏","","",""],[3357,3357,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَضْمَضَ مِنْ لَبَنٍ وَقَالَ إِنَّ لَهُ دَسَمًا ‏","","",""],[3358,3358,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِنْ ‏ ‏أَجْوَدِ النَّاسِ وَأَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏يَلْقَاهُ كُلَّ لَيْلَةٍ يُدَارِسُهُ الْقُرْآنَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ يَلْقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏أَجْوَدَ مِنْ الرِّيحِ الْمُرْسَلَةِ ‏","","",""],[3359,3359,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نُصِرْتُ ‏ ‏بِالصَّبَا ‏ ‏وَأُهْلِكَتْ ‏ ‏عَادٌ ‏ ‏بِالدَّبُورِ ‏","","",""],[3360,3360,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏مُحَمَّدُ بْنُ عَلَيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّهُ بَاتَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَيْقَظَ مِنْ اللَّيْلِ فَأَخَذَ سِوَاكَهُ فَاسْتَاكَ بِهِ ثُمَّ تَوَضَّأَ وَهُوَ يَقُولُ ‏ { ‏إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ ‏} ‏حَتَّى قَرَأَ هَذِهِ الْآيَاتِ وَانْتَهَى عِنْدَ آخِرِ السُّورَةِ ثُمَّ صَلَّى رَكْعَتَيْنِ فَأَطَالَ فِيهِمَا الْقِيَامَ وَالرُّكُوعَ وَالسُّجُودَ ثُمَّ انْصَرَفَ حَتَّى سَمِعْتُ نَفْخَ النَّوْمِ ثُمَّ اسْتَيْقَظَ فَاسْتَاكَ وَتَوَضَّأَ وَهُوَ يَقُولُ حَتَّى فَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ ثُمَّ أَوْتَرَ بِثَلَاثٍ فَأَتَاهُ ‏ ‏بِلَالٌ ‏ ‏الْمُؤَذِّنُ فَخَرَجَ إِلَى الصَّلَاةِ وَهُوَ يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا وَاجْعَلْ فِي سَمْعِي نُورًا وَاجْعَلْ فِي بَصَرِي نُورًا وَاجْعَلْ أَمَامِي نُورًا وَخَلْفِي نُورًا وَاجْعَلْ عَنْ يَمِينِي نُورًا وَعَنْ شِمَالِي نُورًا وَفَوْقِي نُورًا وَتَحْتِي نُورًا اللَّهُمَّ أَعْظِمْ لِي نُورًا ‏","","",""],[3361,3361,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ‏ ‏خَدِيجَةَ ‏ ‏عَلِيٌّ ‏ ‏وَقَالَ مَرَّةً أَسْلَمَ ‏","","",""],[3362,3362,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً ‏","","",""],[3363,3363,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏وَأَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[3364,3364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏أَنْبَأَنَا ‏ ‏ثَابِتٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِلَالٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَبِيتُ ‏ ‏اللَّيَالِيَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏الْمُتَتَابِعَةَ ‏ ‏طَاوِيًا وَأَهْلُهُ لَا يَجِدُونَ عَشَاءً وَكَانَ عَامَّةُ خُبْزِهِمْ خُبْزَ الشَّعِيرِ ‏","","",""],[3365,3365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏أَبُو زَيْدٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُسْرِيَ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏ثُمَّ جَاءَ مِنْ لَيْلَتِهِ فَحَدَّثَهُمْ بِمَسِيرِهِ وَبِعَلَامَةِ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَبِعِيرِهِمْ فَقَالَ نَاسٌ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏نَحْنُ نُصَدِّقُ ‏ ‏مُحَمَّدًا ‏ ‏بِمَا يَقُولُ ‏ ‏فَارْتَدُّوا كُفَّارًا فَضَرَبَ اللَّهُ أَعْنَاقَهُمْ مَعَ ‏ ‏أَبِي جَهْلٍ ‏ ‏وَقَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏يُخَوِّفُنَا ‏ ‏مُحَمَّدٌ ‏ ‏بِشَجَرَةِ ‏ ‏الزَّقُّومِ ‏ ‏هَاتُوا تَمْرًا وَزُبْدًا فَتَزَقَّمُوا وَرَأَى ‏ ‏الدَّجَّالَ ‏ ‏فِي صُورَتِهِ رُؤْيَا عَيْنٍ لَيْسَ رُؤْيَا مَنَامٍ ‏ ‏وَعِيسَى ‏ ‏وَمُوسَى ‏ ‏وَإِبْرَاهِيمَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏ ‏فَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدَّجَّالِ ‏ ‏فَقَالَ ‏ ‏أَقْمَرُ ‏ ‏هِجَانًا ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏قَالَ رَأَيْتُهُ ‏ ‏فَيْلَمَانِيًّا ‏ ‏أَقْمَرَ ‏ ‏هِجَانًا ‏ ‏إِحْدَى عَيْنَيْهِ قَائِمَةٌ كَأَنَّهَا كَوْكَبٌ ‏ ‏دُرِّيٌّ ‏ ‏كَأَنَّ شَعْرَ رَأْسِهِ أَغْصَانُ شَجَرَةٍ وَرَأَيْتُ ‏ ‏عِيسَى ‏ ‏شَابًّا أَبْيَضَ جَعْدَ الرَّأْسِ حَدِيدَ الْبَصَرِ مُبَطَّنَ الْخَلْقِ وَرَأَيْتُ ‏ ‏مُوسَى ‏ ‏أَسْحَمَ ‏ ‏آدَمَ كَثِيرَ الشَّعْرِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏الشَّعَرَةِ ‏ ‏شَدِيدَ الْخَلْقِ وَنَظَرْتُ إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏فَلَا أَنْظُرُ إِلَى ‏ ‏إِرْبٍ ‏ ‏مِنْ ‏ ‏آرَابِهِ ‏ ‏إِلَّا نَظَرْتُ إِلَيْهِ مِنِّي كَأَنَّهُ صَاحِبُكُمْ فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏سَلِّمْ عَلَى ‏ ‏مَالِكٍ ‏ ‏فَسَلَّمْتُ عَلَيْهِ ‏","","",""],[3366,3366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏سُئِلَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏سَأَلْتُ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏الصَّائِمِ أَيَحْتَجِمُ فَقَالَ إِنَّمَا كُرِهَ لِلضَّعْفِ ‏ ‏وَحَدَّثَ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏ثُمَّ ‏ ‏حَدَّثَ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ أَكْلَةٍ أَكَلَهَا مِنْ شَاةٍ مَسْمُومَةٍ سَمَّتْهَا ‏ ‏امْرَأَةٌ ‏ ‏مِنْ أَهْلِ ‏ ‏خَيْبَرَ ‏ ‏آخِرُ أَحَادِيثِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[3367,3367,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏رَمَى الْجَمْرَةَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏مِنْ ‏ ‏بَطْنِ الْوَادِي ‏ ‏ثُمَّ قَالَ هَذَا وَالَّذِي لَا إِلَهَ غَيْرُهُ مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3368,3368,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُدْرِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏لَبَّى حِينَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏فَقِيلَ أَعْرَابِيٌّ هَذَا فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَسِيَ النَّاسُ أَمْ ضَلُّوا سَمِعْتُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏ ‏يَقُولُ فِي هَذَا الْمَكَانِ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ ‏","","",""],[3369,3369,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّانَ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِيَ اقْرَأْ عَلَيَّ مِنْ الْقُرْآنِ قَالَ فَقُلْتُ لَهُ أَلَيْسَ مِنْكَ تَعَلَّمْتُهُ وَأَنْتَ تُقْرِئُنَا فَقَالَ إِنِّي أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَقَالَ اقْرَأْ عَلَيَّ مِنْ الْقُرْآنِ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَيْسَ عَلَيْكَ أُنْزِلَ وَمِنْكَ تَعَلَّمْنَاهُ قَالَ ‏ ‏بَلَى وَلَكِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي ‏","","",""],[3370,3370,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سُورَةِ ‏ ‏النِّسَاءِ ‏ ‏فَلَمَّا بَلَغْتُ هَذِهِ الْآيَةَ ‏ { ‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا ‏} ‏قَالَ ‏ ‏فَفَاضَتْ ‏ ‏عَيْنَاهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3371,3371,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏سَيَّارٌ ‏ ‏وَمُغِيرَةُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏خَصْلَتَانِ ‏ ‏يَعْنِي إِحْدَاهُمَا سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْأُخْرَى مِنْ نَفْسِي ‏ ‏مَنْ مَاتَ وَهُوَ يَجْعَلُ لِلَّهِ نِدًّا دَخَلَ النَّارَ ‏ ‏وَأَنَا أَقُولُ ‏ ‏مَنْ مَاتَ وَهُوَ لَا يَجْعَلُ لِلَّهِ نِدًّا وَلَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏","","",""],[3372,3372,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُبَيْدَةَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏النُّطْفَةَ ‏ ‏تَكُونُ فِي الرَّحِمِ أَرْبَعِينَ يَوْمًا عَلَى حَالِهَا لَا ‏ ‏تَغَيَّرُ فَإِذَا مَضَتْ الْأَرْبَعُونَ صَارَتْ ‏ ‏عَلَقَةً ‏ ‏ثُمَّ ‏ ‏مُضْغَةً ‏ ‏كَذَلِكَ ثُمَّ عِظَامًا كَذَلِكَ فَإِذَا أَرَادَ اللَّهُ أَنْ يُسَوِّيَ خَلْقَهُ بَعَثَ إِلَيْهَا مَلَكًا فَيَقُولُ الْمَلَكُ الَّذِي يَلِيهِ أَيْ رَبِّ أَذَكَرٌ أَمْ أُنْثَى ‏ ‏أَشَقِيٌّ أَمْ سَعِيدٌ أَقَصِيرٌ أَمْ طَوِيلٌ أَنَاقِصٌ أَمْ زَائِدٌ قُوتُهُ وَأَجَلُهُ أَصَحِيحٌ أَمْ ‏ ‏سَقِيمٌ ‏ ‏قَالَ فَيَكْتُبُ ذَلِكَ كُلَّهُ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ فَفِيمَ الْعَمَلُ إِذَنْ وَقَدْ فُرِغَ مِنْ هَذَا كُلِّهِ قَالَ اعْمَلُوا فَكُلٌّ سَيُوَجَّهُ لِمَا خُلِقَ لَهُ ‏","","",""],[3373,3373,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي مُحَمَّدٍ ‏ ‏مَوْلًى ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمَيْنِ يَمُوتُ لَهُمَا ثَلَاثَةٌ مِنْ الْوَلَدِ لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏إِلَّا كَانُوا لَهُ حِصْنًا حَصِينًا مِنْ النَّارِ فَقِيلَ يَا رَسُولَ اللَّهِ فَإِنْ كَانَ اثْنَيْنِ قَالَ وَإِنْ كَانَا اثْنَيْنِ فَقَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏يَا رَسُولَ اللَّهِ لَمْ أُقَدِّمْ إِلَّا اثْنَيْنِ قَالَ وَإِنْ كَانَا اثْنَيْنِ قَالَ فَقَالَ ‏ ‏أُبَيُّ بْنُ كَعْبٍ أَبُو الْمُنْذِرِ ‏ ‏سَيِّدُ الْقُرَّاءِ لَمْ أُقَدِّمْ إِلَّا وَاحِدًا قَالَ فَقِيلَ لَهُ وَإِنْ كَانَ وَاحِدًا فَقَالَ إِنَّمَا ذَاكَ عِنْدَ ‏ ‏الصَّدْمَةِ ‏ ‏الْأُولَى ‏","","",""],[3374,3374,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ الْمُشْرِكِينَ شَغَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏عَنْ أَرْبَعِ صَلَوَاتٍ حَتَّى ذَهَبَ مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ قَالَ قَالَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ أَقَامَ ‏ ‏فَصَلَّى الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ ثُمَّ أَقَامَ فَصَلَّى الْمَغْرِبَ ثُمَّ أَقَامَ فَصَلَّى الْعِشَاءَ ‏","","",""],[3375,3375,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏عَنْ ‏ ‏مُؤْثِرِ بْنِ عَفَازَةَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقِيتُ لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي ‏ ‏إِبْرَاهِيمَ ‏ ‏وَمُوسَى ‏ ‏وَعِيسَى ‏ ‏قَالَ فَتَذَاكَرُوا أَمْرَ السَّاعَةِ فَرَدُّوا أَمْرَهُمْ إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ لَا عِلْمَ لِي بِهَا فَرَدُّوا الْأَمْرَ إِلَى ‏ ‏مُوسَى ‏ ‏فَقَالَ لَا عِلْمَ لِي بِهَا فَرَدُّوا الْأَمْرَ إِلَى ‏ ‏عِيسَى ‏ ‏فَقَالَ أَمَّا ‏ ‏وَجْبَتُهَا ‏ ‏فَلَا يَعْلَمُهَا أَحَدٌ إِلَّا اللَّهُ ذَلِكَ وَفِيمَا ‏ ‏عَهِدَ ‏ ‏إِلَيَّ رَبِّي عَزَّ وَجَلَّ أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏خَارِجٌ قَالَ وَمَعِي قَضِيبَانِ فَإِذَا رَآنِي ذَابَ كَمَا يَذُوبُ الرَّصَاصُ قَالَ فَيُهْلِكُهُ اللَّهُ حَتَّى إِنَّ الْحَجَرَ وَالشَّجَرَ لَيَقُولُ يَا مُسْلِمُ إِنَّ تَحْتِي كَافِرًا فَتَعَالَ فَاقْتُلْهُ قَالَ فَيُهْلِكُهُمْ اللَّهُ ثُمَّ يَرْجِعُ النَّاسُ إِلَى بِلَادِهِمْ وَأَوْطَانِهِمْ قَالَ فَعِنْدَ ذَلِكَ يَخْرُجُ ‏ ‏يَأْجُوجُ ‏ ‏وَمَأْجُوجُ ‏ ‏وَهُمْ مِنْ كُلِّ ‏ ‏حَدَبٍ ‏ ‏يَنْسِلُونَ ‏ ‏فَيَطَئُونَ بِلَادَهُمْ لَا يَأْتُونَ عَلَى شَيْءٍ إِلَّا أَهْلَكُوهُ وَلَا يَمُرُّونَ عَلَى مَاءٍ إِلَّا شَرِبُوهُ ثُمَّ يَرْجِعُ النَّاسُ إِلَيَّ فَيَشْكُونَهُمْ ‏ ‏فَأَدْعُو اللَّهَ عَلَيْهِمْ فَيُهْلِكُهُمْ اللَّهُ وَيُمِيتُهُمْ حَتَّى ‏ ‏تَجْوَى ‏ ‏الْأَرْضُ مِنْ نَتْنِ رِيحِهِمْ قَالَ فَيُنْزِلُ اللَّهُ عَزَّ وَجَلَّ الْمَطَرَ فَتَجْرُفُ أَجْسَادَهُمْ حَتَّى يَقْذِفَهُمْ فِي الْبَحْرِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏ذَهَبَ عَلَيَّ هَاهُنَا شَيْءٌ لَمْ أَفْهَمْهُ ‏ ‏كَأَدِيمٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏ثُمَّ تُنْسَفُ الْجِبَالُ وَتُمَدُّ الْأَرْضُ ‏ ‏مَدَّ ‏ ‏الْأَدِيمِ ‏ ‏ثُمَّ رَجَعَ إِلَى حَدِيثِ ‏ ‏هُشَيْمٍ ‏ ‏قَالَ فَفِيمَا عَهِدَ إِلَيَّ رَبِّي عَزَّ وَجَلَّ أَنَّ ذَلِكَ إِذَا كَانَ كَذَلِكَ فَإِنَّ السَّاعَةَ كَالْحَامِلِ الْمُتِمِّ الَّتِي لَا يَدْرِي أَهْلُهَا مَتَى تَفْجَؤُهُمْ بِوِلَادِهَا لَيْلًا أَوْ نَهَارًا ‏","","",""],[3376,3376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ فُلَانًا نَامَ الْبَارِحَةَ عَنْ الصَّلَاةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ الشَّيْطَانُ بَالَ فِي أُذُنِهِ ‏ ‏أَوْ فِي أُذُنَيْهِ ‏","","",""],[3377,3377,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ صُبَيْحٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏مَسْرُوقٍ ‏ ‏فِي بَيْتٍ فِيهِ تِمْثَالُ ‏ ‏مَرْيَمَ ‏ ‏فَقَالَ ‏ ‏مَسْرُوقٌ ‏ ‏هَذَا تِمْثَالُ ‏ ‏كِسْرَى ‏ ‏فَقُلْتُ لَا وَلَكِنْ تِمْثَالُ ‏ ‏مَرْيَمَ ‏ ‏فَقَالَ ‏ ‏مَسْرُوقٌ ‏ ‏أَمَا إِنِّي سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الْمُصَوِّرُونَ ‏","","",""],[3378,3378,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ هُوَ الْأَزْرَقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَنْبَغِي لَهُ أَنْ يَتَمَثَّلَ بِمَثَلِي ‏","","",""],[3379,3379,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يَحْزُنُهُ ‏","","",""],[3380,3380,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ فَقَامُوا صَفَّيْنِ فَقَامَ صَفٌّ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَفٌّ مُسْتَقْبِلَ الْعَدُوِّ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّفِّ الَّذِينَ يَلُونَهُ رَكْعَةً ثُمَّ قَامُوا فَذَهَبُوا فَقَامُوا مَقَامَ أُولَئِكَ مُسْتَقْبِلَ الْعَدُوِّ وَجَاءَ أُولَئِكَ فَقَامُوا مَقَامَهُمْ فَصَلَّى بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَةً ثُمَّ سَلَّمَ ثُمَّ قَامُوا فَصَلَّوْا لِأَنْفُسِهِمْ رَكْعَةً ثُمَّ سَلَّمُوا ثُمَّ ذَهَبُوا فَقَامُوا مَقَامَ أُولَئِكَ مُسْتَقْبِلَ الْعَدُوِّ وَرَجَعَ أُولَئِكَ إِلَى مَقَامِهِمْ فَصَلَّوْا لِأَنْفُسِهِمْ رَكْعَةً ثُمَّ سَلَّمُوا ‏","","",""],[3381,3381,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ الْجَزَرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏عَلَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّشَهُّدَ وَأَمَرَهُ أَنْ يُعَلِّمَ النَّاسَ ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[3382,3382,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نُسَلِّمُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الصَّلَاةِ فَيَرُدُّ عَلَيْنَا فَلَمَّا رَجَعْنَا مِنْ عِنْدِ ‏ ‏النَّجَاشِيِّ ‏ ‏سَلَّمْنَا عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْنَا فَقُلْنَا يَا رَسُولَ اللَّهِ كُنَّا نُسَلِّمُ عَلَيْكَ فِي الصَّلَاةِ فَتَرُدُّ عَلَيْنَا فَقَالَ ‏ ‏إِنَّ فِيَّ ‏ ‏أَوْ فِي ‏ ‏الصَّلَاةِ لَشُغْلًا ‏","","",""],[3383,3383,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضْلُ صَلَاةِ الرَّجُلِ فِي الْجَمَاعَةِ عَلَى صَلَاتِهِ وَحْدَهُ بِضْعٌ وَعِشْرُونَ دَرَجَةً ‏","","",""],[3384,3384,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَتَى لَيْلَةُ الْقَدْرِ قَالَ ‏ ‏مَنْ يَذْكُرُ مِنْكُمْ لَيْلَةَ الصَّهْبَاوَاتِ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَا بِأَبِي أَنْتَ وَأُمِّي وَإِنَّ فِي يَدِي لَتَمَرَاتٍ ‏ ‏أَسْتَحِرُ ‏ ‏بِهِنَّ مُسْتَتِرًا ‏ ‏بِمُؤْخِرَةِ رَحْلِي ‏ ‏مِنْ الْفَجْرِ وَذَلِكَ حِينَ طَلَعَ الْقَمَرُ ‏","","",""],[3385,3385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ خَمْسًا فَقِيلَ زِيدَ فِي الصَّلَاةِ قِيلَ صَلَّيْتَ خَمْسًا فَسَجَدَ سَجْدَتَيْنِ ‏","","",""],[3386,3386,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَمِيعِ تَفْضُلُ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ خَمْسَةً وَعِشْرِينَ ضِعْفًا كُلُّهَا مِثْلُ صَلَاتِهِ ‏","","",""],[3387,3387,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلِ بْنِ مُقَرِّنٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أَبِي عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَقَالَ أَنْتَ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّدَمُ تَوْبَةٌ قَالَ نَعَمْ ‏ ‏وَقَالَ ‏ ‏مَرَّةً سَمِعْتُهُ يَقُولُ النَّدَمُ تَوْبَةٌ ‏","","",""],[3388,3388,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ مَهَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ وَلَوْ مِنْ حُلِيِّكُنَّ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ فَقَامَتْ امْرَأَةٌ لَيْسَتْ مِنْ عِلْيَةِ النِّسَاءِ فَقَالَتْ لِمَ يَا رَسُولَ اللَّهِ قَالَ لِأَنَّكُنَّ تُكْثِرْنَ ‏ ‏اللَّعْنَ ‏ ‏وَتَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏","","",""],[3389,3389,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَهُمَا بَعْدَ السَّلَامِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ السَّجْدَتَيْنِ فِي السَّهْوِ بَعْدَ السَّلَامِ ‏","","",""],[3390,3390,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَلِيَ رَجُلٌ مِنْ أَهْلِ بَيْتِي ‏ ‏يُوَاطِئُ ‏ ‏اسْمُهُ اسْمِي ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا بِهِ فِي بَيْتِهِ فِي غُرْفَتِهِ أُرَاهُ سَأَلَهُ بَعْضُ وَلَدِ ‏ ‏جَعْفَرِ بْنِ يَحْيَى ‏ ‏أَوْ ‏ ‏يَحْيَى بْنِ خَالِدِ بْنِ يَحْيَى ‏","","",""],[3391,3391,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَنْقَضِي الْأَيَّامُ وَلَا يَذْهَبُ الدَّهْرُ حَتَّى يَمْلِكَ ‏ ‏الْعَرَبَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏بَيْتِي اسْمُهُ ‏ ‏يُوَاطِئُ ‏ ‏اسْمِي ‏","","",""],[3392,3392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَذْهَبُ الدُّنْيَا ‏ ‏أَوْ قَالَ لَا تَنْقَضِي الدُّنْيَا ‏ ‏حَتَّى يَمْلِكَ ‏ ‏الْعَرَبَ ‏ ‏رَجُلٌ مِنْ أَهْلِ بَيْتِي ‏ ‏وَيُوَاطِئُ ‏ ‏اسْمُهُ اسْمِي ‏","","",""],[3393,3393,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَارٍ فَنَزَلَتْ عَلَيْهِ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏فَأَخَذْتُهَا مِنْ ‏ ‏فِيهِ وَإِنَّ فَاهُ لَرَطْبٌ بِهَا فَلَا أَدْرِي بِأَيِّهَا خَتَمَ ‏ { ‏فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ ‏} ‏أَوْ ‏ { ‏قِيلَ لَهُمْ ارْكَعُوا لَا يَرْكَعُونَ ‏} ‏سَبَقَتْنَا حَيَّةٌ فَدَخَلَتْ فِي جُحْرٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏وُقِيتُمْ شَرَّهَا وَوُقِيَتْ شَرَّكُمْ ‏","","",""],[3394,3394,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نُسَلِّمُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏قَبْلَ أَنْ نَأْتِيَ أَرْضَ ‏ ‏الْحَبَشَةِ ‏ ‏فَلَمَّا قَدِمْنَا مِنْ أَرْضِ ‏ ‏الْحَبَشَةِ ‏ ‏أَتَيْنَاهُ فَسَلَّمْنَا عَلَيْهِ فَلَمْ يَرُدَّ فَأَخَذَنِي مَا قَرُبَ وَمَا بَعُدَ حَتَّى قَضَوْا الصَّلَاةَ فَسَأَلْتُهُ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحْدِثُ فِي أَمْرِهِ مَا يَشَاءُ وَإِنَّهُ قَدْ أُحْدِثَ مِنْ أَمْرِهِ أَنْ لَا نَتَكَلَّمَ فِي الصَّلَاةِ ‏","","",""],[3395,3395,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَامِعٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ ‏ ‏يَقْتَطِعُ ‏ ‏بِهَا مَالَ مُسْلِمٍ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ وَقَرَأَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِصْدَاقَهُ مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا أُولَئِكَ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُمْ فِي الْآخِرَةِ وَلَا يُكَلِّمُهُمْ اللَّهُ ‏}","","",""],[3396,3396,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَامِعٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعُ عَبْدٌ زَكَاةَ مَالِهِ إِلَّا جُعِلَ لَهُ ‏ ‏شُجَاعٌ ‏ ‏أَقْرَعُ يَتْبَعُهُ يَفِرُّ مِنْهُ وَهُوَ يَتْبَعُهُ فَيَقُولُ أَنَا كَنْزُكَ ثُمَّ قَرَأَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مِصْدَاقَهُ فِي كِتَابِ اللَّهِ ‏ { ‏سَيُطَوَّقُونَ مَا بَخِلُوا بِهِ يَوْمَ الْقِيَامَةِ ‏} ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً يُطَوَّقُهُ فِي عُنُقِهِ ‏","","",""],[3397,3397,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْزَلَ اللَّهُ دَاءً إِلَّا قَدْ أَنْزَلَ لَهُ شِفَاءً عَلِمَهُ مَنْ عَلِمَهُ وَجَهِلَهُ مَنْ جَهِلَهُ ‏","","",""],[3398,3398,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شِمْرٍ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ بْنِ سَعْدِ بْنِ الْأَخْرَمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَتَّخِذُوا ‏ ‏الضَّيْعَةَ ‏ ‏فَتَرْغَبُوا فِي الدُّنْيَا ‏","","",""],[3399,3399,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّتِهِ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏وَإِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3400,3400,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏سَمِعْتُ ‏ ‏شَقِيقًا ‏ ‏يَقُولُ ‏ ‏كُنَّا نَنْتَظِرُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فِي الْمَسْجِدِ يَخْرُجُ عَلَيْنَا فَجَاءَنَا ‏ ‏يَزِيدُ بْنُ مُعَاوِيَةَ يَعْنِي النَّخَعِيَّ ‏ ‏قَالَ فَقَالَ أَلَا أَذْهَبُ فَأَنْظُرَ فَإِنْ كَانَ فِي الدَّارِ لَعَلِّي أَنْ أُخْرِجَهُ إِلَيْكُمْ فَجَاءَنَا فَقَامَ عَلَيْنَا فَقَالَ إِنَّهُ لَيُذْكَرُ لِي مَكَانُكُمْ فَمَا آتِيكُمْ كَرَاهِيَةَ أَنْ أُمِلَّكُمْ لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ فِي الْأَيَّامِ كَرَاهِيَةَ ‏ ‏السَّآمَةِ ‏ ‏عَلَيْنَا ‏","","",""]];
